INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本の著作権法第30条の4は、AI学習における著作物の利用を原則として「許諾不要」と定めている。この規定が設けられた法的・政策的意図として最も適切なものはどれか。', '["AI開発におけるイノベーションの阻害要因を排除し、情報解析の環境を整えるため","著作権者の権利を完全に無効化し、パブリックドメイン化を促進するため","AIの出力物が既存の著作物と同一であることを法的に保証するため","クリエイターの利益を保護するために、学習データを無制限に公開させるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「表現とアイデアの二分論」に基づき、著作権保護が及ぶ範囲と及ばない範囲の境界について述べた記述として、最も適切なものはどれか。', '["思想や感情そのものやアイデアは保護の対象だが、具体的な表現は保護されない","具体的な表現は保護の対象となるが、その背後にある抽象的なアイデアやテーマは保護の対象外である","AIが学習に使用したデータであれば、表現であっても一切の著作権主張が不可能となる","著作権法は表現の類似性のみを問い、アイデアの模倣については道徳的非難の対象外である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '生成AIによる著作権侵害を認定する際の要件として、「依拠性」と「類似性」がある。「依拠性」の定義として最も正確なものはどれか。', '["AIが学習したデータがインターネット上に公開されている事実","AIモデルが生成物を作る際に、特定の著作物を実際に利用・参照していること","生成物を見た人間が、元の著作物と似ていると主観的に感じること","AI開発企業が著作権者に対して使用許諾を得ていたかどうかという行政手続き上の事実"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現在の著作権法第30条の4において、例外的に利用が制限される（許諾が必要となる）ケースとして、条文が明示しているものはどれか。', '["著作権者の利益を不当に害する場合","AIによる生成物のクオリティが低い場合","学習データを海外のサーバーに転送する場合","営利目的で生成AIを利用する場合"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AIによる学習と「著作物の利用」に関して、クリエイター側が懸念している論点として妥当なものはどれか。', '["AIが学習過程で著作物の表現を完全にコピーして保存し、それをそのまま再配布する点","AIが特定の作家の画風や文体を模倣した作品を大量生成し、元の作家の市場的価値を毀損する点","AIによるデータ解析そのものが、作家の表現の自由を奪う行為である点","AI開発者が学習データを著作権者に還元しなければならないという法的義務に違反している点"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '生成AIが「画風」や「文体」を学習し、それに基づいた新たな作品を生成することについて、現在の著作権法の解釈として一般的なものはどれか。', '["画風や文体は「表現」そのものであり、著作権で保護されるため、学習は常に違法である","画風や文体は「アイデア（創作的様式）」に該当し、原則として著作権保護の対象外である","画風や文体は著作権法ではなく、不正競争防止法のみで厳格に保護されている","AIが学習した時点で、その画風や文体に関する著作権はAI開発者に帰属する"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「利益衡量」の視点から、AI学習を巡る議論において考慮すべき対立軸の組み合わせとして最も適切なものはどれか。', '["AI開発の技術革新を通じた社会全体の利益と、個々のクリエイターの創作的インセンティブの維持","国家の経済成長と、個人の表現の自由の完全な保障","プログラミング技術の発展と、既存の出版社やマスメディアの独占的利益","著作権者の完全な制御権と、AIによる自動生成物の完全な合法化"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AIが生成した出力物が著作権侵害であると判断されるために必要な要件は何か。', '["AIが人間の脳と同じ仕組みで学習していること","生成物が既存の著作物に依拠し、かつそれと実質的に類似していること","AI開発者が商用利用によって多額の利益を得ていること","学習データとして使用された著作物が、高額で販売されていたこと"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '著作権法における「享受目的」と「非享受目的」の区別がなぜ重要なのか、その理由として適切なものはどれか。', '["著作物を「享受（鑑賞）」するために利用する場合は許諾が必要だが、解析（非享受）目的の場合は柔軟な利用が許容されるため","「享受目的」であればAI学習が可能だが、「非享受目的」では法律上、学習が禁じられているため","著作権法は、鑑賞用作品と解析用作品を厳密に分け、後者にのみ著作権を認めているため","「享受目的」のみがクリエイターの生活を支える唯一の手段であると定義されているため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AI学習データとして著作物を利用する際の「適法範囲」に関する懸念として、倫理的に最も議論の的となっているものはどれか。', '["AIが短時間で学習を終えてしまうこと","著作権者が自身の作品がどのようなAIモデルに使われているか把握できないという透明性の欠如","学習データがすべて日本語で構成されていること","AIが物理的な書籍を破壊してデータ化していること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'オプトアウト（利用拒否）の仕組みが議論される理由として最も適切なものはどれか。', '["クリエイターが自身の著作物をAIの学習から除外したいという意思を表明する権利を保障するため","AI開発者がすべての著作権者から個別に許諾を得るコストを法的に義務付けるため","AI生成物が誤情報を含んでいた場合に、クリエイターが法的な責任を問われないようにするため","すべての学習データから著作物を完全に抹消し、AI開発を停止させるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AI生成物そのものに著作権が発生するか否かについて、現在の日本の文化庁の見解として妥当なものはどれか。', '["AIが生成したものであれば、どのような内容でも自動的に著作権が発生する","AIが生成したものでも、人間が創作的意図を持って活用し、創作的寄与が認められる場合は著作権が発生しうる","AIの出力物はすべてAIが著作権者となるため、人間には権利が発生しない","AI生成物は法律上「物」ではないため、著作権法は一切適用されない"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '著作権法第30条の4における「著作権者の利益を不当に害する場合」とは、具体的にどのような状況を想定しているか。', '["AIの学習結果が市場において元の著作物と直接的な代替関係となり、著作物の販売機会を著しく損なう場合","クリエイターが個人的にAIの学習技術を理解していない場合","AIが学習データを元に創作活動を行うことで、将来的なクリエイターの数が増える場合","AI開発者が無料でAIツールを一般公開している場合"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「依拠性」を立証することが難しいとされる主な要因はどれか。', '["AIの学習データが膨大であり、AIがどのデータを参照して生成したかを遡る「ブラックボックス」問題があるため","著作権者が自分の作品が使われている証拠を隠蔽しているため","日本の法律が著作権者の権利を認めていないため","AI生成物はすべてランダムに生成されており、元データとの関連性がないため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AI学習を巡る法制度設計において、「イノベーションの推進」と「著作権保護」を両立させるための現代的なアプローチとして注目されているものはどれか。', '["著作権法の完全廃止","オプトアウト制度の整備と、学習データの透明性を確保するための技術的・法的枠組みの構築","クリエイター全員に対してAI利用を義務付けること","AIが生成したすべての作品を自動的に著作権侵害と認定するシステムの導入"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '著作権法第30条の4が適用されるための条件として「情報解析」という言葉が用いられている。この「情報解析」に該当しないと解釈される可能性が高い行為はどれか。', '["AIモデルを構築するために膨大な文章を形態素解析し、統計的パターンを抽出する行為","AIの学習を目的とせず、単に作品をコピーして観賞用としてサーバーに保存する行為","特定の著作物の構成要素をデータ化し、傾向を分析する行為","複数の書籍から特定のキーワードを抽出し、データベースを作成する行為"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AIが既存の著作物の「表現上の本質的な特徴」を直接複製したとみなされる場合の法的帰結はどれか。', '["複製権や翻案権の侵害となり、著作権侵害の責任を問われる可能性がある","AIが生成したものであれば、AIには責任がないため法的な罰則は適用されない","表現上の本質的な特徴を複製することは、AI技術においては学習の一環として常に免責される","文化庁の許可があれば、著作権者の同意なしに販売が可能となる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '小論文の論題として「生成AIと著作権」を扱う際、バランスの取れた多角的視点を論じるための構成案として最も優れたものはどれか。', '["AI技術がもたらす経済的利益と利便性を全面的に肯定し、反対派の意見を無視して論じる","現行法の規定を解説するのみで、自身の意見を一切述べない","技術発展の必要性と著作権保護の重要性を双方から提示した上で、持続可能な共生のあり方を提案する","クリエイターの権利保護を最優先とし、AIの技術開発を全面的に規制すべきだと主張する"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AI時代における「創作」の概念の変化として、最も論理的な考察はどれか。', '["AIを使えば誰でも芸術家になれるため、個人の感性は不要になった","AIが生成するとしても、人間による選択、編集、指示といったプロセスが新たな「創作的寄与」として再評価されるようになる","AIの出現により、人間の手による芸術的営みは完全に時代遅れとなり、消滅する","著作権法は人間のみを対象とするため、AI生成物は創作物と呼ぶこと自体が不可能である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '次の文章は、ある法学者によるAI学習に関する議論の要約である。この文脈において「利益衡量」が指し示している本質は何か。『技術の進歩は社会の共有財産であるが、それが特定のクリエイターの生存を脅かす場合、社会全体としての法的な調整が必要となる』', '["AIの権利を優先し、人間の著作権を消滅させるべきだということ","技術革新と既存の権利保護の間での最適なバランスを見出すこと","経済的利益のみを計算し、最も儲かる方を法的に正当化すること","AI開発を法的に禁じることが社会全体の利益に直結するということ"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'EUの一般データ保護規則（GDPR）が規定する「忘れられる権利」の核心的な意義として、最も適切なものはどれか。', '["インターネット上の全ての情報を永久に削除する権利","個人のプライバシー保護と情報の公共性・記憶の文脈を調整する権利","公的機関が保持する全ての個人情報を無条件に抹消させる権利","誤った情報を拡散したメディアを法的に処罰する権利"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'スマートシティにおいて、都市の効率化と個人のプライバシーが衝突する背景として、最も論理的に妥当なものはどれか。', '["利便性の追求には詳細な個人データの集約と分析が不可欠であり、それが監視の常態化を招くため","都市機能の管理が全てAIに委ねられることで、人間の意思決定が完全に排除されるため","プライバシー権を主張することは、現代社会におけるテクノロジーの発展を全面的に否定することと同義であるため","スマートシティは治安維持を最優先するため、そもそも個人の権利は考慮されない設計であるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '顔認証技術が公共空間に導入される際、懸念される「同意の形式化」という問題の本質は何か。', '["技術的に同意を撤回することが不可能であるという物理的な制約","公共空間での歩行者が事実上選択の余地なく監視を受け入れざるを得ない状況","顔認証の結果が常に誤判定を含んでいるという技術的限界","政府による監視のみを想定し、民間企業の利活用が無視されている点"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'データプロファイリングがもたらす「パーソナライゼーション（最適化）」の逆説として、適切でないものはどれか。', '["個人の選択の幅が狭まり、フィルターバブルによって価値観が固定化される","広告ターゲティングの精度が高まり、市場全体の取引コストが上昇する","個人の行動予測が経済的インセンティブと結びつき、行動変容を無意識に促される","情報の非対称性により、企業が特定の個人に対して不利な条件を提示するリスクが生じる"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「自己情報コントロール権」の定義において、最も重視される視点はどれか。', '["個人が自らの情報を誰に、どのような目的で開示・利用させるかを主導的に決定する権利","公的機関に対して自らの情報を完全に隠蔽し、一切の関与を拒絶する権利","インターネット上の全ての個人情報を無料で閲覧・編集する権利","国家が収集するあらゆるデータを即座に開示させる権利"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'プライバシーの保護を「社会的な対抗権」と捉える際、監視社会への防壁となる概念はどれか。', '["情報の透明性の確保と、監視の主体に対する監視（対抗監視）","個人の行動を完全に隠匿し、社会との関わりを断絶すること","政府の治安維持政策に全面的に追従することで権利を確保すること","プライバシー保護を市場原理に委ね、企業間の競争に任せること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パノプティコン的な監視構造が現代のデジタル社会で再現されていると言われる最大の理由は何か。', '["物理的な刑務所と異なり、監視されている側が「いつ見られているか」を意識せずに自己検閲を強いる環境があるため","インターネット上では個人の行動が物理的に完全に拘束されているため","監視の目的が犯罪抑止というよりも、完全に個人の娯楽のためであるため","政府が全市民に対して強制的にチップの埋め込みを義務付けているため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'GDPRにおいて求められる「データ最小化の原則」を正しく説明したものはどれか。', '["個人データの収集は、目的達成に必要な最小限の範囲に限定しなければならないという原則","データの収集量を減らすことで、サーバーのコストを抑えることを目的とした原則","どのようなデータであっても、無条件で削除し続けなければならないという原則","政府機関以外は、個人データを一切収集してはならないという原則"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会的な信用スコア制度が抱える倫理的リスクとして、最も重大なものは何か。', '["スコアの計算方法が複雑で、一般市民が数学的に理解できない点","多様な個人の価値を単一の数値に還元し、社会的な選別や排除を自動化する恐れがある点","スコアが高い人に対する優遇措置が不公平であるという経済学的問題","システムを運用するための電力消費が環境負荷を高めるという点"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'スマートシティが提唱する「データ駆動型社会」において、公共性の概念が変容する側面として最も適切なものはどれか。', '["公共の利益が、合意形成ではなくデータに基づく最適解によって定義される傾向がある","公共性は全て個人の自由な選択の総和に過ぎないと解釈されるようになる","物理的な空間よりも仮想空間での体験のみが公共性として重視されるようになる","公共の概念が消滅し、全てが民間の所有物として扱われるようになる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「プライバシー」を単なる「秘密の保持」以上のものと捉える現代的な解釈として、最も適切なものはどれか。', '["自己のアイデンティティを形成し、自由な対人関係を維持するための不可欠な空間","外部から完全に隔絶された密室での生存を保証するもの","法的に認められた、どのような犯罪も隠蔽できる権利","他者からの干渉を一切受けず、完全に自己完結した社会生活を送る権利"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'デジタル監視の強化が、「個人の自律性」を損なう可能性があるという論理的根拠は何か。', '["常に監視されているという意識が、個人の判断や行動を社会的に望ましいと定義される平均的な型へ誘導するため","個人の思考が直接的に読み取られ、意思決定の自由が生物学的に失われるため","政府がすべての国民の職業を強制的に割り当てるようになるため","デジタル監視によって個人の経済力がすべて奪われるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '公共の安全を理由とした監視社会化を推進する立場の論理として、しばしば用いられるものはどれか。', '["安全とプライバシーはトレードオフの関係にあり、高度な安心のためにはプライバシーの一部譲渡はやむを得ない","プライバシー権はすでに時代遅れの概念であり、守るべき価値はない","デジタル監視を行えば、すべての人間から犯罪の動機を完全に消去できる","プライバシー権を認めることは、国家の存立を危うくする絶対的悪である"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '行動経済学的な知見に基づいた「ナッジ（nudge）」が、データプロファイリングと組み合わされた際に生じる問題はどれか。', '["個人の無意識的な選択が誘導されているにもかかわらず、それが本人の意思による自由な選択だと誤認させられること","物理的な強制力によって行動が制限され、人権侵害が明白になること","データの精度が極めて低く、経済活動が混乱するリスク","ナッジを用いることで、すべての人間が全く同じ行動をとるよう強制されること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '技術決定論（テクノロジーが社会のあり方を必然的に決定するという考え方）に対する批判として、最も適切なものはどれか。', '["技術の利用方法や規制のあり方は社会的な意思決定に委ねられており、技術発展は単なる一要因に過ぎない","技術は常に人間に益をもたらすものであり、社会が適応すべき対象である","技術の進化を止めることは不可能であり、どのような社会問題も技術で解決できる","プライバシー保護は技術の進化を阻害する最大の障害である"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「忘れられる権利」に関して、メディアや表現の自由と対立する局面として最も妥当なものはどれか。', '["過去の犯罪歴や不祥事について、情報の公共性と個人の更生・平穏な生活のバランスをどこで取るか","すべてのニュースを24時間以内に消去しなければならないという強迫観念","メディアが権力者を批判することを禁止する理由となる","インターネット上に一度アップロードされた表現を、誰であっても削除できないという絶対性"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'スマートシティにおける「デジタル・デバイド」が、監視社会の不平等を生むという指摘の本質は何か。', '["技術を使いこなせない層が、効率化の恩恵を受けられないだけでなく、過剰な監視の対象になりやすいこと","デジタル機器を持たない人々のプライバシーが完全に守られるという不公平","技術に詳しい富裕層のみが監視から逃れられるという社会構成","スマートシティがそもそも富裕層以外を都市から排除するように設計されているという点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '匿名加工情報が持つ社会的な役割とリスクの組み合わせとして、最も適切なものはどれか。', '["役割：データ活用による社会的利便性の向上 / リスク：再識別による個人のプライバシー暴露","役割：個人の特定を容易にする / リスク：情報の流出を防ぐ","役割：個人の同意を不要にする / リスク：国家による完全な統制の実現","役割：個人の行動を完全に隠す / リスク：経済活動の停滞"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '監視カメラやセンサーから得られるデータを「公共財」と見なす考え方について、批判的に検討すべき点は何か。', '["そのデータが本当に公共のために使われているのか、あるいは特定の企業の利益のみに還元されていないか","データは無形であり、公共財としての法的な定義が既に確立されているため議論の余地がない","すべてのデータは、そもそも国家が所有するものであり、公共財という概念は不要である","データは個人の持ち物であり、公共財として扱うこと自体が不可能である"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'デジタル時代における「プライバシー」の保護を、人権の文脈で考える際、最も根本となる思想はどれか。', '["人間は誰しも、自らの領域を他者から守り、その中で自律的に生きていく権利を持つという思想","国家の指示に忠実に従うことが、個人の最大の幸福であるという思想","個人のデータは共有されるべきものであり、秘密を持つことは利己的であるという思想","デジタル社会では個人の情報は全て公開されるべきであるという思想"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ゲノム編集技術において、治療（セラピー）と能力増強（エンハンスメント）を区別する議論がなされる最大の論理的理由は何か。', '["病気の治療は医学的妥当性に基づく回復であるが、エンハンスメントは身体的機能の枠組みを逸脱する改変であり、個人のアイデンティティや公平性に深刻な影響を及ぼすから。","エンハンスメント技術は現在の科学力では物理的に不可能であるため、議論の対象外であるから。","国連の国際条約において、治療とエンハンスメントの分類が法的に明確に規定されているから。","両者はともに個人の自由選択に属するものであり、倫理的に区別する必要性は全く存在しないから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「デザイナーベビー」の創出を懸念する論者が、生命の尊厳に関して最も警戒する点は何か。', '["子どもが親の期待に応えるための道具として扱われ、自律的な存在としての権利が損なわれる可能性。","ゲノム編集を行うことで、生物としての生存率が著しく低下してしまう懸念。","政府が国民のゲノム情報を収集し、監視社会を構築しようとするリスク。","特定の遺伝的特徴を持つ子どもを増やすことが、宗教的な教義に反するという見解。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデル教授が『完全な人間を目指さなくてもよい理由』において批判した「優生学的願望」とは、どのような心理や社会構造を指すか。', '["偶然に左右される生命のあり方を、親が支配し操作しようとする傲慢さと、それによる連帯感の喪失。","生物学的な多様性を守るために、特定の病気を根絶しようとする積極的な公衆衛生政策。","すべての人類が平等な遺伝的特性を持つべきであると主張する社会主義的な思想。","科学技術の発展によって、すべての病気が克服される未来を信じる楽観的な進歩主義。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '生殖細胞系列へのゲノム編集（受精卵や生殖細胞への介入）が、体細胞への介入と比べて特に慎重に扱われる主な理由は何か。', '["改変が次世代以降に受け継がれ、人類の遺伝子プールを不可逆的に変えてしまうリスクがあるから。","技術的に生殖細胞への操作の方が、体細胞よりも遥かに難易度が高く成功率が低いから。","生殖細胞を操作することは、現在の法制度ではいかなる理由があっても唯一禁じられているから。","個体の生存には影響がないが、操作を行うと必ずその個体が不妊になるという医学的事実があるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「負の優生学」と「正の優生学」の違いを定義する場合、適切な記述はどれか。', '["負は特定の遺伝性疾患の排除を目指し、正は知能や容姿などの特性向上を促進しようとするものである。","負は国家が強制的に行う介入であり、正は個人の自発的な選択による介入のことである。","負は生存している個体への介入であり、正は未来の世代に対する介入のことである。","負は劣等な遺伝子を削除する技術であり、正は優秀な遺伝子を合成して創り出す技術のことである。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ゲノム医療の普及に伴う「遺伝的格差」の拡大を懸念する論理的帰結として、最も適切なものはどれか。', '["経済的強者が高度なゲノム改変技術を享受することで、生物学的にも階層が固定化され、社会的不平等が永続化する恐れ。","遺伝的格差は努力によって克服可能であるため、社会的な介入は不必要であるという結論。","ゲノム技術が安価に普及することで、人類全員が同様の身体能力を持ち、逆に競争が激化する懸念。","国家が国民の遺伝的健康状態を管理することで、社会保障費が劇的に削減されるという楽観的な予測。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'CRISPR-Cas9などのゲノム編集技術が、従来の遺伝子組み換え技術（GMO）と比較して革命的と言われる技術的要因は何か。', '["標的となる特定のDNA配列を、極めて高い精度かつ簡便な手法で狙い撃ちし、切断・修正できるようになったこと。","細胞内での突然変異を全く誘発せず、100%の成功率で遺伝子を書き換えることが可能になったこと。","外部から導入する遺伝子を用いずに、細胞が持つ既存の機能を停止させることのみに特化した技術であること。","すべての生物種において、同じ遺伝子操作を行えば必ず同じ表現型が現れることが証明されたこと。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '生命倫理における「インフォームド・コンセント」が、胎児に対するゲノム編集の議論において適用困難とされるのはなぜか。', '["対象となる胎児（将来の人間）自身が、同意を与えることが物理的に不可能であるから。","親が子どものために最善を尽くすことは、倫理的に常に肯定されるべきであるから。","遺伝子改変による健康上のメリットが、本人の意志よりも優先されると法的に決まっているから。","出生前の検査技術が未発達であり、同意を取る以前にリスクを予測できないから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ノーマライゼーション」の観点から見て、ゲノム編集による疾患の根絶を目指す動きを批判する論点は何か。', '["疾患を持つ人々を排除の対象と見なす社会風潮を助長し、多様なあり方を許容する寛容性を損なう懸念。","特定の遺伝的特性を消すことは、生物の進化を止める行為であり、医学的成功にはつながらないという主張。","全ての病気を治すことは経済的に不可能であり、資源の無駄遣いであるという費用対効果の観点。","障がい者がゲノム編集を受けることを拒否しているという、当事者主権の原則に基づく主張。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「自然の摂理」を尊重すべきだとする論理（自然主義的論拠）が、ゲノム編集技術に対して抱く主要な違和感とは何か。', '["人間が自然を制御可能な対象として扱うことは、謙虚さを欠いており、予期せぬ生態学的崩壊を招くという懸念。","人間の身体は神によって設計されたものであり、いかなる理由があろうと改変は罪であるという宗教的な主張。","科学は常に人間に害を与えるものであり、技術の進歩を止めることが地球環境保護に繋がるという思想。","ゲノム改変は自然界に存在しないため、いかなる生物学的な根拠も持ち得ないという科学的懐疑論。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '遺伝子の決定論的視点（Genetic Determinism）に立つリスクについて、社会学的に最も適切な指摘は何か。', '["個人の性格や運命を遺伝子だけで説明しようとすると、環境要因や個人の努力を軽視し、過度な管理社会を招く恐れがあること。","遺伝子さえ解析すれば、将来の犯罪者や成功者を完璧に予測できることが、最新の科学によって証明されたこと。","すべての人類が遺伝的に同一であれば、社会的な摩擦や紛争は完全に解決されるという理論。","遺伝子は一度決まると死ぬまで一切変化しないという生物学的な絶対真理に基づいた考え方。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「偶然性」が生命に与える重要性について、サンデルの議論に見られる考え方はどれか。', '["生を自らの努力で完全に管理するのではなく、与えられた条件を受け入れる姿勢こそが、他者への寛容や謙虚さを生む。","偶然性は、技術革新を促進するための単なる障壁であり、排除されるべきものである。","遺伝的な偶然性は、不平等の源泉であるため、技術的に完全に克服することが正義である。","人間は偶然性を制御する能力を唯一備えた存在であり、それを行使することは義務である。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ゲノム編集を用いた「適応」と「増強」の境界が、文脈によって揺らぐことを示す例として適切なのはどれか。', '["視力を回復させる治療が、視力を超人レベルまで高める増強技術と技術的基盤を共有しており、線引きが困難なこと。","遺伝子の改変はどのような理由であれ、必ず全人類に対して等しく提供されるため、区別は無意味であること。","「適応」は常に政府主導で行われ、「増強」は常に個人主導で行われるため、管理の主体が異なること。","一度「治療」として認められた技術は、将来的に二度と「増強」には応用できないと法的に規定されていること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '公衆衛生の観点から、ゲノム編集による「集団免疫の向上」を肯定する立場が直面する倫理的ジレンマは何か。', '["個人の遺伝的自己決定権を、社会全体の健康維持のために侵害してよいのかという問題。","ゲノム編集された集団は、従来の人間とは異なる種として法的に認定されるべきかという問題。","病気を克服した社会では、逆に新しい病原体が進化しやすくなるという生物学的なパラドックス。","ゲノム編集を行うためのコストが、全ての市民に均等に分配されないことに対する不公平感。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'CRISPR-Cas9技術の「オフターゲット変異」のリスクが、倫理的に重要視されるのはなぜか。', '["意図しない遺伝子領域が切断・修正されることで、がんの発生など予測不能な健康被害が生じる可能性があるから。","技術の特許権を巡る企業間の争いが、医療現場の混乱を招いているから。","オフターゲット変異が起きた場合、その個体は法的に「人間」としての定義を失うから。","このリスクを公表することは、科学者としての倫理に反する行為だと学会で定められているから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療の「パターナリズム（父権的干渉）」が、ゲノム医療の現場で批判的に議論される理由は何か。', '["専門家や医師が患者の意思を無視して「より良い遺伝子」を押し付けることが、個人の自律性を損なうから。","患者が希望する治療法を、医師がすべて無条件に受け入れるべきであるという主張が、医療の質を下げるから。","医療費を削減するために、医師が国家の指示に従って特定の治療を拒否する行為。","親が子どもに対する医療の決定権を独占し、子どもが成長した後の意思を完全に無視できるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「優生思想の再来」を指摘する識者が、現代のゲノム技術に抱く最も本質的な懸念は何か。', '["国家による強制的な断種ではなく、消費者の選択や市場原理を通じて「劣った遺伝子の排除」が浸透していくこと。","昔の優生学者が行っていたような、科学的根拠のない差別的な言説が再び流行していること。","現代の科学者が、優生学的な動機を隠さずに、公然と人間改造を提唱していること。","特定の国々が、軍事目的でのみゲノム編集技術を隠密に使用し続けていること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ゲノム医療において、「遺伝情報のプライバシー」が極めて重要視される論理的な根拠は何か。', '["遺伝情報は個人の最も究極的な個人情報であり、その開示が保険加入、就職、結婚等における深刻な差別を誘発する可能性があるから。","遺伝情報を他者に知られることは、生物学的に自身の身体の一部を奪われることに等しいという宗教的な教えだから。","一度公開された遺伝情報は、法的にコピーが制限されず、誰でも不正に利用できるから。","遺伝情報を隠すことは法律違反であり、罰則が厳格に定められているから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '人間が自らの設計図（ゲノム）を書き換える行為に対して、「プロメテウス的」という比喩が用いられる場合、その含意は何か。', '["神の領域である生命創造の火を人間が盗み取り、その力によって破滅を招くリスクを警告するニュアンス。","人類の文明を飛躍的に発展させ、すべての苦痛から解放する希望の象徴としてのニュアンス。","自然界には存在しない新しい生物種を次々と作り出し、生態系の頂点に立つという傲慢な宣言。","人間とAIが融合する未来において、人類が次の進化段階へ進むための儀式であるという主張。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ゲノム編集技術に関する「グローバル・ガバナンス（世界的な管理体制）」の構築が喫緊の課題となっている理由は何か。', '["一国の規制を潜り抜けて規制の緩い国で実験が行われる「科学の観光旅行」を防ぎ、全人類規模での倫理基準を担保するため。","世界中のすべての科学者が、単一の国際的なゲノム編集プロジェクトに参加することが義務付けられているから。","ゲノム技術の利用が、すでに地球外生命体との外交問題に発展しているから。","すべての国がゲノム編集技術を国家機密としており、国際的な情報共有が不可能であるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'J.S.ミルが『自由論』で提唱した「他者危害原則」が、現代の医療倫理におけるパターナリズムの正当化を困難にさせている主な理由はどれか。', '["本人の身体に対する決定権は、他者に危害を及ぼさない限り、社会や国家が介入すべきではないから。","医療技術の高度化により、個人の意思に関わらず生存を優先させることが医学的義務となったから。","他者危害原則は宗教的な道徳観に基づいており、世俗的な医療現場には適用できないから。","個人の自己決定は、常に家族の幸福と密接に結びついており、不可分であると見なされるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'インフォームド・コンセントの概念において、医師が患者に提供すべき情報の核心として最も適切なものはどれか。', '["医師が最も医学的に有効だと判断した治療方針のみを伝えること。","医療上のリスクと利益、および代替治療法について患者が理解可能な形で説明すること。","患者の家族の同意が確実に得られるような説得的言辞を尽くすこと。","最新の医学的知見を網羅し、患者が専門的判断を医師に全面的に委任させること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「弱いパターナリズム」と「強いパターナリズム」の境界線に関する説明として、最も論理的なものはどれか。', '["患者が判断能力を失っている場合のみに介入するのが強いパターナリズムである。","患者の意思に反しても、その利益のために介入するのが強いパターナリズムである。","医師個人の良心に基づく介入が弱いパターナリズムで、法律に基づく介入が強いパターナリズムである。","経済的なコストを考慮して医療行為を制限することが強いパターナリズムである。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '尊厳死に関する議論において、「生命の神聖性（Sanctity of Life）」を重視する立場から、安楽死や積極的安楽死に対して投げかけられる論理的批判として最も適切なものはどれか。', '["苦痛の除去は医学的に不可能であり、無意味な努力であるから。","生命は個人の所有物ではなく、人為的に終結させることは倫理的に許容し得ないから。","安楽死を認めると、医療費の削減が国家の主要な目的となってしまうから。","個人の権利は社会全体の福祉に優先するという考え方が浸透していないから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療現場における「自律性（Autonomy）」の尊重が困難に直面する状況として、最も典型的なものはどれか。', '["医師が高度な専門性を持ち、患者に選択肢を提示している場合。","患者が認知機能や意識の低下により、自発的な意思決定が困難な場合。","患者が医療保険制度を十分に理解し、費用を支払う能力がある場合。","家族全員が患者の治療方針について完全に合意している場合。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '安楽死が認められた社会において懸念される「滑り坂論法（Slippery Slope Argument）」の具体的な内容はどれか。', '["安楽死の合法化が、本人の意思に関わらず社会的弱者の排除を招く恐れがあるという指摘。","安楽死を選択した患者が、死後にどのような法的手続きをとるべきか混乱を招くという懸念。","医師の技術力が低下し、誤診によって死に至る事故が増加するリスク。","安楽死を選択する人が増えることで、医療従事者のモチベーションが低下すること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療における「最善の利益（Best Interests）」の判断主体が、患者本人から家族や医師へ移らざるを得ないのはどのような状況か。', '["患者が事前に十分な経済的備えをしていなかった場合。","患者の価値観が不明であり、かつ意思疎通が不能な状態にある場合。","患者が希望する治療法が、医学的に最新のものではない場合。","患者が宗教的な理由で輸血を拒否しようとしている場合。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '積極的安楽死と消極的安楽死（または尊厳死）の倫理的な峻別の根拠として、しばしば引用される「作為と不作為」の議論において正しい説明はどれか。', '["作為的な行為は常に悪であり、不作為は常に善であるとする絶対的規範。","意図的に死を早める行為（作為）と、回復の見込みのない延命治療を差し控えること（不作為）を区別する考え方。","作為は医師の過失であり、不作為は患者の権利であるという法的解釈。","作為は科学的な行為であり、不作為は感情的な判断であるという分類。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'リビング・ウィル（事前指示書）が、現代の終末期医療において重要視される最大の理由はどれか。', '["医師が訴訟リスクを回避し、法的責任を免除されるために不可欠だから。","本人が意識を失った後でも、自身の自己決定権を尊重させるための手段となり得るから。","家族の心理的な負担を軽減し、相続問題を円滑に進めるためだから。","社会保障費の削減という公的な目的を達成するために必須だから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療現場において、医師の「善行原則（Beneficence）」が、患者の「自己決定権」と衝突する場合の適切な対応として、現代倫理で推奨されるものはどれか。', '["医師の専門的判断を最優先し、患者を説得して治療を強制する。","患者の自己決定を絶対視し、医学的に明らかな誤りであっても一切介入しない。","対話を通じて互いの価値観を共有し、患者が十分な理解のもとで合意できるよう支援する。","患者の決定を保留し、病院の倫理委員会が決定を下すまで待機する。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「尊厳ある死」という概念が、単に「苦痛なく死ぬこと」以上の意味を持つ理由として、最も適切なものはどれか。', '["死ぬまでの期間、患者が自分自身の生の意味を自律的に定義し続けることを含意するから。","法律が定める手続きに従って死亡することが、最も尊厳があるから。","死後の葬儀が手厚く行われることが尊厳の定義であるから。","苦痛を伴わない死こそが、唯一医学的に正しい死の形態であるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代医療において、医療情報の非対称性（医師と患者の知識格差）が、パターナリズムの温床となりやすい理由として適切なものはどれか。', '["患者が自発的に無知であることを選択しているから。","医師のみが医学的情報の解釈権を持ち、患者の判断を誘導することが容易だから。","社会が医師に対して過度な法的責任を求めているから。","医学的知識は公開されておらず、患者が学習することが不可能だから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '終末期医療において、医師が患者の「治療拒否」を尊重することは、医学倫理上どのように位置づけられるか。', '["医師の殺人幇助にあたるため、許容されない。","患者の自律的な権利行使であり、尊重されるべき重要な医療倫理の構成要素である。","病院の経営効率を低下させる行為であるため、避けるべきである。","家族が同意しない限り、医師は決して患者の要求を飲んではならない。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '患者が「自己決定権」を行使する前提条件として、特に重視される概念はどれか。', '["高い学歴と専門的な医療知識。","判断能力（コンピテンス）が保持されていること。","医師に対して完全に服従する姿勢。","経済的な余裕と保険の適用有無。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「代理決定（Surrogate Decision-making）」を行う際、家族や代理人に求められる倫理的な判断基準として最も適切なものはどれか。', '["自分がもし患者であったらどうするかという個人的好みの反映。","患者が健常時であればどう判断したかという「推論的判断」に基づいた決定。","病院にとって最も管理上の負担が少ない治療法の選択。","医師が提案した治療法を無条件に承認すること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '緩和ケアが普及することで、安楽死に対するニーズが抑制される可能性があるという主張の根拠として適切なものはどれか。', '["安楽死は違法であると法律で強く定めれば、誰も要望しなくなるから。","患者の苦痛（身体的・精神的）を適切に緩和すれば、死ぬこと以外の選択肢が生まれるから。","緩和ケアは安楽死よりも短時間で実施できるため、効率が良いから。","安楽死を望む患者は、単に医療費の支払いを拒否しているだけだから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本のような家族主義的な文化を持つ社会において、インフォームド・コンセントが西洋と異なる形をとる場合がある理由として、最も妥当なものはどれか。', '["日本人は契約よりも信頼関係や家族との合意を重視する傾向があるため、個人の決断が孤立を招くことを懸念するから。","日本には患者の権利を尊重する法律が存在しないから。","日本人は医学的説明を理解する能力が平均的に低いから。","日本では医師が患者の家族に対して全ての決定権を譲渡する法的義務があるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「クオリティ・オブ・ライフ（QOL）」という概念が、現代医療の意思決定において重視されるようになった背景はどれか。', '["生存期間の延長のみを追求する医療から、個人の生の意味や満足度を尊重する医療への転換。","死期を早めることで医療費を抑えようとする政府の政策方針。","医師の労働時間を削減し、効率的に患者を診察するための指標。","患者の家族が、患者に対して経済的な援助を行うか否かを判断する基準。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '自己決定権が「絶対的な権利」ではないとされる理由として、最も論理的なものはどれか。', '["自己決定が社会的なコストや他者の権利に悪影響を及ぼす場合、制限される余地があるから。","医師が患者の意思決定を無効にする法的な権利を持っているから。","自己決定権は西洋の思想であり、東洋文化圏には適合しないから。","死に関わる決定は個人の尊厳以前に、神の領域であるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'アドバンス・ケア・プランニング（ACP）が重視される理由は何か。', '["将来的な意思決定の困難に備え、あらかじめ価値観や意向を対話によって共有しておくことが不可欠だから。","全ての患者に安楽死を奨励するための準備プロセスだから。","病院のスタッフのスキルアップを目的とした教育研修プログラムだから。","法律家が医療現場に介入し、患者の権利を代弁しやすくするためだから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パンデミック下において、限られた人工呼吸器をどの患者に配分するかという「トリアージ」の倫理的ジレンマにおいて、功利主義（utilitarianism）的アプローチが目指す究極の目的として最も適切なものはどれか。', '["特定の属性を持つ個人を優先的に救済する権利の保護","救命可能な人数を最大化し、社会全体の総利益を最適化すること","医療従事者の精神的負荷を最小限に抑えること","先着順で配分し、手続き上の公平性を完全に担保すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ジョン・ロールズの「公正としての正義」に基づき、パンデミックにおける医療資源配分を議論する際、最も重視される視点はどれか。', '["社会に貢献する可能性が高い個人の能力主義的評価","最も不遇な境遇にある人々の利益を最大限に図る「格差原理」の適用","多数決によって決定された社会的価値観の直接的反映","資源配分における行政の裁量権の無制限な拡大"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「臨床的トリアージ」と「公衆衛生上のトリアージ」の決定的な相違点として、最も適切な説明はどれか。', '["臨床的は救える命を重視し、公衆衛生上は社会経済的地位を重視する","臨床的は個々の患者の最善を追求し、公衆衛生上は集団全体の生存を追求する","臨床的は医師の個人的直感を重視し、公衆衛生上は法律的判例のみを根拠とする","臨床的は緊急性を無視し、公衆衛生上は年齢のみで判断する"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「生命の質（QOL）」という概念をトリアージの判断基準に導入する際の論理的課題として、最も妥当な指摘はどれか。', '["QOLは客観的かつ絶対的な指標であり、倫理的問題を引き起こさない","QOLの評価には個人の価値観や障害者差別などの倫理的懸念が伴う","QOLを導入すれば、医療従事者の過重労働が自動的に解消される","QOLは技術的コストを削減するためにのみ開発された概念である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「医療資源の配分において、社会的価値や貢献度を基準にすべきではない」という考え方の根拠として、最も適切なものはどれか。', '["人間の生命は本質的に平等であり、功利的な計算で軽重を測るべきではないから","社会的価値を定義する公的機関が存在しないため、実務的に不可能だから","医師は患者の社会的身分を知る権利を法律で制限されているから","社会貢献度は常に医療技術の進歩によって否定されるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '災害やパンデミック時の「公平性（equity）」を論じる際、単なる「平等（equality）」との違いとして捉えるべき点は何か。', '["平等は結果の均等であり、公平は機会の均等である","平等は個別のニーズを考慮せず一律に扱うこと、公平は必要な人に必要な資源を届けることである","平等は政府の義務であり、公平は市民個人の寄付によるものである","平等は緊急時にのみ適用され、公平は平時にのみ適用される"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'トリアージにおける「救命優先順位」として、「救命の可能性が高い患者を優先する」という判断基準が持つ倫理的帰結について、適切な説明はどれか。', '["重症度が高い患者を見捨てることになるため、生命の平等原則と対立する","結果として社会的に富裕層のみが救われる仕組みである","生存確率が低い患者の治療を放棄することは、医療者の法的免責を伴わない","この基準を採用することで、医療資源の不足が恒久的に解決する"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パンデミックにおける公衆衛生政策において、「パターナリズム（父権主義）」が批判される理由として、最も適切なものはどれか。', '["個人の自律的な意思決定権を損ない、国家による過度な介入を正当化する恐れがあるから","医療従事者の技術不足を隠蔽するための手段として利用されるから","パターナリズムは常に医療費の削減を目的としているから","パターナリズムは人種差別を助長する歴史的背景を持つから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「年齢に基づいたトリアージ（例：高齢者より若年者を優先）」がしばしば提案される倫理的根拠である「ライフサイクル原理」の説明として、最も妥当なものはどれか。', '["誰しもが人生の各段階を経験する機会を持つべきであり、若年者はまだその機会を十分に享受していないという考え","高齢者は社会に貢献し終えたため、死を受け入れるべきであるという考え","若年者の方が肉体的な労働生産性が高いため、経済的損失が少ないという考え","高齢者の延命治療は常に失敗するという医学的統計に基づく考え"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'トリアージの決定権を個々の医師に委ねることのリスクとして、最も懸念される点はどれか。', '["医師個人の主観的偏見や疲労が判断に混入し、一貫性が損なわれること","医師の医療技術が向上せず、古い治療法に固執することになること","病院の経営効率が優先され、利益が最大化されること","個々の医師に法的責任が集中し、医療崩壊が加速すること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パンデミック下において、「医療資源の配分基準」を事前に明文化しておくことの最大の利点は何か。', '["現場の医師の心理的負担を軽減し、手続き上の透明性と社会的合意を確保できること","すべての患者を確実に救うことができるようになること","公衆衛生当局による監視を不要にすること","医療資源を無制限に増産できる環境を整えること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療資源配分の文脈における「手続き的正義」とは何を意味するか。', '["配分の結果がどうあれ、決定に至るプロセスが公正で透明であり、異議申し立てが可能であること","最も多くの票を集めた意見を常に採用すること","法律の専門家のみが決定に関与すること","過去の慣習に基づき、機械的に判断を下すこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「危害原理（ミル）」に基づき、パンデミック下で個人の自由（外出制限等）を制限する場合の正当化の条件として、適切なものはどれか。', '["他人に危害を加えることを防止するためにのみ、権力を行使することができる","国家が個人の幸福を最大限にするためにのみ権力を行使できる","大多数が同意すれば、いかなる理由でも個人の自由を制限できる","経済成長を阻害する個人の行動を禁止できる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'トリアージの議論において「インフォームド・コンセント」が極めて困難になる主な理由は何か。', '["緊急時であり、患者に説明を受ける時間も判断能力も期待できない場合が多いため","医師が患者に真実を隠すことが医療界の慣習となっているため","患者側の法的代理人が存在しないことが一般的であるため","治療方法が高度すぎて患者が理解不可能であるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パンデミックにおける公衆衛生の概念を「社会の防衛」と捉える際、個人の権利との間で生じる対立の本質はどれか。', '["共同体全体の生存維持と、個人の自己決定権の衝突","科学技術の発展と、宗教的価値観の衝突","国家の軍事的防衛と、市民の自由な経済活動の衝突","中央政府の決定と、地方自治体の権限の衝突"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '医療資源配分において「公平な抽選（ロッタリー）」という手法が提案されることがある。これが採用される主な倫理的背景はどれか。', '["社会的価値や年齢による差別を避け、すべての生命を平等に扱うため","医療従事者の能力に関わらず、結果を運に委ねることで責任を回避するため","最も早く手続きが終わる効率的な手法であるため","統計学的に救命率が最も高くなることが証明されているため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'パンデミック対応において「持続可能性（サステナビリティ）」を考慮すべきであるという主張の論理的根拠はどれか。', '["医療体制が崩壊すれば、パンデミック以外の病気による死者も増加するため","病院経営者が経済的な持続可能性を重視しているため","医療資源の供給者が環境問題を懸念しているため","長期間のロックダウンが環境破壊を抑止するため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「二重結果の原理」をトリアージの文脈で解釈した場合、適切なものはどれか。', '["救命を意図した医療行為によって、結果的に患者が死亡しても、それは不当な殺人と同義ではない","二つの薬を同時に使用することで、予後が二倍良くなること","患者を救うことと、医者を守ることは常に相反する結果を生むこと","成功確率が低い治療を行うことは、意図的に死を選択することである"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代の公衆衛生倫理において「説明責任（アカウンタビリティ）」が重視される最大の理由は何か。', '["誰を救い誰を見捨てるかという決定が、民主的な国家において国民の信頼を損なう恐れがあるから","裁判に備えて記録を残すことが法律で義務付けられているから","医療機器メーカーが責任の所在を明確に求めているから","国際機関からの監視が強化されているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「生命を救うための優先順位」を考える際に、「社会的有用性」を用いることへの反対意見として最も強力なものはどれか。', '["誰が何を「有用」と判断するかという基準の客観的妥当性が担保できず、社会的弱者の排除につながるから","経済的に余裕がある人が高額な治療を独占すべきであるという結論に直結するから","効率化を求めると、医療技術の進歩が停止してしまうから","社会的有用性を考慮すると、若年者の教育が疎かになるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カーボンニュートラル実現に向けた『エネルギーのトリレンマ』において、最も調和を図ることが困難とされる要素の組み合わせはどれか。', '["環境適合性と経済性","エネルギーセキュリティと環境適合性","経済性と安定供給","安定供給と環境適合性"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '再生可能エネルギーの主力電源化が進む中で生じる「出力変動問題」に対処するための解決策として、最も論理的に妥当なものはどれか。', '["化石燃料火力発電の即時全廃","蓄電池技術の向上とデマンドレスポンスの推進","原子力発電の完全な代替としての再エネ化","送電網の孤立化による地域ごとの自給自足"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '欧州連合（EU）が推進する「カーボン・ボーダー調整措置（CBAM）」が、国際貿易において果たそうとしている役割として最も適切なものはどれか。', '["発展途上国への直接的な技術移転資金の拠出","環境規制が緩やかな国からの輸入品に対する炭素コストの課金","世界的な炭素税の一律引き下げ交渉","自国内の製造業の完全な撤退支援"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '原子力発電を「グリーン」なエネルギー源として分類すべきか否かという議論において、支持派が主たる根拠として挙げる論理はどれか。', '["放射性廃棄物の処分場問題の完全な解決","発電過程における二酸化炭素排出量の圧倒的な低さ","再エネ発電よりも高いコスト効率","地域社会への経済的な波及効果"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「脱炭素社会への移行」において生じる「公正な移行（Just Transition）」とは、どのような概念を指すか。', '["環境規制を全業種に一律に適用すること","移行過程で雇用や地域経済に打撃を受ける労働者・地域を社会的に保護すること","先進国が発展途上国の資源を優先的に確保すること","炭素税の徴収をすべての国民から平等に行うこと"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本のような資源小国において、エネルギー安全保障を確保するために必要な「電源ミックス（ベストミックス）」の考え方として最も適切なものはどれか。', '["単一のエネルギー源に依存することで管理コストを下げる","特定の国からの輸入に依存して調達を安定させる","再エネ、原子力、火力等を組み合わせることでリスクを分散させる","すべてのエネルギーを国内自給できる体制を構築する"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カーボンニュートラルにおける「スコープ3」排出量とは、何を指すものか。', '["自社が使用する電力から直接排出される温室効果ガス","製品の原料調達から廃棄・リサイクルに至るサプライチェーン全体の排出量","自社の工場や車両から直接排出される温室効果ガス","政府が定めた排出枠を超えることで発生する超過分"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「脱炭素」と「経済成長」を両立させる「GX（グリーントランスフォーメーション）」において、民間企業に期待される最も重要な行動はどれか。', '["環境規制を避けるための生産拠点の海外移転","化石燃料依存型のビジネスモデルの維持とコスト削減","脱炭素に関連する技術革新への積極的な投資と事業転換","環境保護活動への寄付による社会的責任の充足"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '電力供給における「ベースロード電源」の重要性が説かれる背景として、最も適切なものはどれか。', '["天候に左右されず、低コストで安定した電力供給が可能であること","温室効果ガスを全く排出しないこと","蓄電池を不要にするための唯一の手段であること","発電所の立地場所が容易に選定できること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '気候変動対策としての「カーボンプライシング」が導入される経済学的な主目的は何か。', '["炭素排出量に応じて罰金を科すことで、企業の利益を国が徴収する","排出の外部不経済を価格に内部化し、低炭素技術への投資を促す","エネルギー価格を一律に引き上げることで国民の消費を抑制する","輸入製品を排除して自国の製造業を保護する"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '水素エネルギーが脱炭素社会の鍵を握るとされる理由のうち、化学的・物理的な観点から最も妥当なものはどれか。', '["水素は核融合反応を起こしやすいため","燃焼時に二酸化炭素を排出せず、水しか生成しないため","エネルギー密度が蓄電池よりも遥かに低いため","製造過程で全くエネルギーを消費しないため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '再生可能エネルギーの導入拡大が進むことで生じる「送電網（グリッド）」の課題として、最も重要なものはどれか。', '["送電線の色が環境に与える視覚的負荷","発電地と消費地の乖離および出力変動に伴う調整力の確保","送電網のメンテナンスに必要な人材の不足","電気の電圧を統一するためのコスト増"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「サーキュラーエコノミー（循環型経済）」への転換がカーボンニュートラルに寄与する論理的理由はどれか。', '["製品を廃棄せずに再利用することで、資源採掘や加工による排出を抑制する","経済活動を完全に停止させることで環境負荷をゼロにする","再利用可能な素材を使用することで、炭素税を免除される","輸入に頼らず、国内の廃棄物のみで製造を行うため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '原子力発電の廃炉において直面する最大の倫理的・技術的課題はどれか。', '["廃炉に必要な資金が極端に少ないこと","放射性廃棄物の長期的な最終処分場の選定と管理","解体技術が世界的にまだ開発されていないこと","廃炉プロセスが気候変動の原因になること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '環境保護を最優先するあまり、発展途上国の経済発展を阻害するという批判がある。この文脈における「環境の帝国主義」とはどのような主張か。', '["先進国が環境基準を押し付け、途上国の工業化を制限しているという批判","途上国が環境を保護せずに発展することへの羨望","すべての国が平等に炭素を排出できるべきだという主張","先進国が自国の環境保護のために途上国の資源を搾取しているという批判"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「分散型電源」がエネルギー安全保障において有するメリットとして最も適切なものはどれか。', '["全国一律の電力網を構築することで停電を防ぐ","集中型電源への依存を減らし、災害時などのレジリエンス（回復力）を高める","発電コストを最大限に削減できる","大規模な発電所を建設する手間を省ける"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本のエネルギー政策における「2030年度温室効果ガス46%削減目標」の達成に向けて、最も困難が予想されるボトルネックは何か。', '["目標数値に対する国民の関心の低さ","産業構造の転換スピードと、既存の電力インフラの制約","海外からのエネルギー輸入が容易であること","科学技術が未発達であること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '炭素中立の議論において「ネガティブ・エミッション」が注目される理由はどれか。', '["経済成長を完全に止める必要があるため","排出削減だけでは達成不可能な残余分を吸収・除去する必要があるため","温室効果ガスを地球外へ排出する技術を指すため","すべての化石燃料の使用を正当化するため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '再生可能エネルギーの固定価格買取制度（FIT）の功罪として、最も頻繁に議論されるのはどれか。', '["導入の加速を促した一方、国民の負担（賦課金）が増大した","再エネ発電所を減少させた一方で、火力発電のコストを下げた","電力の安定供給を確実にしたが、技術革新を停滞させた","国営企業のみに利益をもたらした"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '環境規制を導入した際、国内産業が海外へ移転し、結果として地球規模の排出量が削減されない現象を何と呼ぶか。', '["炭素リーケージ（カーボン・リーケージ）","グリーンウォッシュ","環境ダンピング","市場の失敗"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「コモンズの悲劇」という概念を提唱したギャレット・ハーディンが、自由放任な利用が悲劇を招くと論じた根本的な理由として、最も適切なものはどれか。', '["個人の合理的選択が、集団全体の利益を損なう結果をもたらすから","共有資源に対する人々の認識が不足しており、情報共有がなされていないから","政府による介入が過剰になり、民間主導の技術革新が阻害されるから","人口爆発により資源の物理的な量が絶対的に枯渇し、分配の正当性が失われるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'エリノア・オストロムが主張した、コモンズを適切に管理するための「自治的ガバナンス」の要件として誤っているものはどれか。', '["外部の権力による強制的な管理体制の構築","境界が明確に定義された資源管理の単位","利用状況を監視し、違反者に対して段階的な制裁を課す仕組み","資源の利用者がルールの変更に参画できる民主的な手続き"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代の資本主義社会における「GDP（国内総生産）」の限界について、小論文の論点として最も妥当な視点はどれか。', '["自然資本の毀損や社会的格差といった「負の側面」を反映できない点","公共財の生産を過大評価し、市場経済の活性化を隠蔽している点","幸福度指数（GNH）よりも成長率を重視する国際的な枠組みが皆無である点","技術革新による生産性向上を計算式から除外しているため、過小評価である点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「脱成長論」が提唱する経済的ビジョンの本質的な目的はどれか。', '["経済成長という指標を目的化することをやめ、地球環境の制約内での充足を求めること","すべての市場経済を解体し、原始的な物々交換社会へと回帰すること","科学技術の発展を禁止し、エネルギー消費をゼロに近づけること","国家の主権を廃止し、グローバル企業による資源管理に移行すること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サーキュラーエコノミー（循環型経済）が、従来の「リサイクル型経済」と決定的に異なる点は何か。', '["廃棄物を出すことを前提とせず、製品設計の段階から資源の循環を組み込む点","すべての製品を公的機関が回収し、効率的に再利用する強制的な法整備を行う点","リサイクルコストを価格に転嫁することで、消費行動を抑制する点","再生可能エネルギーの導入を重視し、資源の再利用には言及しない点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「定常型社会」論において、人口や資本のストックを一定に保つための経済的条件として最も重要なものはどれか。', '["資源の消費量と廃棄量を、自然の再生産・吸収能力の範囲内に収めること","市場における金利を完全に撤廃し、通貨の価値をゼロに近づけること","グローバルな競争を促進し、国際的な価格競争力を最大化すること","すべての産業を国有化し、政府が資源分配を中央集権的に管理すること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ハーディンが提示した「相互的な強制による相互的な合意」という解決策が、現代の環境問題に対して抱える倫理的な課題はどれか。', '["個人の自由や自律的な選択を犠牲にする独裁的・専制的な管理に傾斜する懸念","資源の私有化を促進することで、貧困層の権利を保障する機能が強化される点","科学的根拠を無視して、多数決による恣意的な資源管理が行われること","過度に地域分権化が進み、地球規模の環境問題を解決できないこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'コモンズにおける「フリーライダー（ただ乗り）」問題とは、どのような状況を指すか。', '["資源管理の努力を他者に任せ、自分だけが利益を享受してコストを負担しないこと","資源を過剰に搾取し、将来世代の利用可能性を完全に奪うこと","市場競争に参加せず、自給自足の生活を営む個人が孤立すること","公的な支援を受けずに、自力で環境保護活動を行うボランティアのこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「人新世（Anthropocene）」という言葉が含意する、人間活動と環境の関係性として正しいものはどれか。', '["人間活動が地層に痕跡を残すほど、地球の生態系に決定的な変容を与えているという認識","人間は自然の一部であり、環境変化に対して受動的な存在であるという定義","産業革命以前の状態に地球を完全に戻すことが、唯一の解決策であるとする主張","人間中心主義を克服し、動物の権利を法的に平等に認めるべきという倫理観"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '資本主義経済における「外部不経済」として、環境問題の文脈で最も適切に説明されているものはどれか。', '["企業の生産活動が、市場価格に反映されない形で環境負荷や公害を社会に転嫁すること","公共サービスの不足により、経済活動が停滞し失業率が上昇すること","市場取引が行われない家庭内の労働が、経済統計に含まれないこと","海外企業からの投資が国内産業を圧迫し、不当な競争が生じること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '持続可能な発展（サステナブル・デベロップメント）という概念が、現代社会においてしばしば批判の対象となる最大の理由はどれか。', '["「成長」と「環境保護」を両立できるという前提が、成長神話への依存を招いているため","途上国の経済発展を完全に否定し、先進国のみが利益を独占しようとする論理だから","環境保護を主導するNGOが、国際政治において過剰な影響力を持っているため","技術革新のスピードが遅すぎると見なされ、政策立案者が無策であるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'コモンズを「共有地」から「コモン（共有財）」へと再定義する現代思想において、重視されている視点はどれか。', '["資源を単なるモノとしてではなく、人々の対話やケアを通じて維持される関係性として捉えること","土地を完全に国有化し、国家による平準化された配分を求めること","資源をデジタル技術で効率化し、誰でも匿名で利用可能にすること","個人の私有権を強化し、市場競争を通じて管理の効率性を競わせること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サーキュラーエコノミーの実現において、製品の「設計（デザイン）」が最も重要とされる理由は何か。', '["製品の寿命、修理可能性、素材の再利用性を段階で決定づけるから","消費者の美的感覚を満たすことが、製品の長寿命化に直結するから","デザインの特許権を独占することが、企業の競争力の源泉になるから","安価な素材を使うことで、経済的な効率性を最大化できるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「脱成長」派が主張する「ケアの経済」が、従来の経済学的な評価と対立する理由はどれか。', '["金銭的な報酬を伴わない育児や介護を、経済的な重要性において最優先すべきだと考えるから","医療や福祉を民営化し、競争原理を導入することで効率化を図ろうとするから","市場価格こそが人間の価値を測る唯一の尺度であると主張するから","労働時間を増大させ、生産効率を追求することを推奨しているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '共有資源の管理において、「私有化」が必ずしも「悲劇」の解決にならないケースとして適切なものはどれか。', '["海や大気のように、境界を確定させることが物理的に困難な資源の場合","土地を私有化することで、不当な価格高騰が起こり資源が効率的に配分される場合","民間企業が高度な技術で資源を採掘し、収益を地域に還元する場合","政府による補助金で私有化を促進し、農地の生産性が劇的に向上する場合"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代のグローバル・サプライチェーンにおいて、廃棄物や環境負荷が「見えにくくなっている」最大の要因は何か。', '["生産拠点が環境規制の緩い途上国に移転し、消費地と分離されているから","環境保護に関する国際条約が、多国籍企業の活動を監視できていないから","インターネット上の情報流通が、製品の製造過程を過度に隠蔽しているから","物流技術の向上により、製品の移動距離が短縮され追跡が困難になったから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ハーディンの「コモンズの悲劇」に対する、オストロムの批判的な問いかけの本質は何か。', '["中央集権的な管理か私有化かという二元論に陥らず、コミュニティによる管理の可能性を提示した点","市場経済の仕組みを最大限に活用し、政府の介入を完全に排除すべきだと論じた点","資源の利用を禁止し、自然保護区を拡大することこそが唯一の正解だと説いた点","人口増加を止めるための厳格な法的強制力の行使を支持した点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '環境と経済を両立させる議論において、「デカップリング（脱結合）」が意味するものはどれか。', '["経済成長に伴う環境負荷の増大を、技術革新等によって切り離すこと","環境問題を解決するために、経済活動を完全に停止させること","政治と経済を切り離し、企業の自主的な判断に環境問題を委ねること","都市部と農村部の経済的格差を解消し、均等な発展を目指すこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サーキュラーエコノミーにおいて、「製品（プロダクト）」から「サービス」へのシフトが進む最大の意義は何か。', '["所有から利用への転換により、メーカーに長寿命で修理しやすい製品を作る動機を与えるため","消費者が製品を所有することで、心理的な満足感が得られなくなっているため","製品の価格を下げることで、市場全体の取引数を劇的に増やすため","サービスの提供を通じて、個人の嗜好データを細かく収集するため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '定常型社会や脱成長論が直面する政治的な困難として、最も適切なものはどれか。', '["経済成長の停止が、現行の年金や社会保障制度の維持を困難にするという懸念","国家間の軍事競争が、成長の抑制という政策を事実上不可能にしている点","国民の多くが、環境意識よりも目先の消費行動を優先してしまうという国民性の問題","脱成長を提唱する政治家が、科学技術の発展を否定していると誤解されがちな点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベンサムの提唱した「最大多数の最大幸福」という功利主義的原理において、個人の権利や利益が制限される正当な根拠として最も適切なものはどれか。', '["個人の尊厳は公共の福祉よりも常に絶対的に優先されるため制限は許されない。","幸福の総量を最大化させるために、個別の犠牲を上回る全体の利益が得られる場合。","個人の権利は神から授けられた不可侵の法であり、誰にも制限することはできない。","少数の不幸が多数の幸福を補完するという歴史的必然性が認められるため。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントが提示した「定言命法」の定義として最も正確なものはどれか。', '["自分の欲望を充足させるための手段として、状況に応じて選択すべき行動基準。","もし幸福になりたいならば、誠実であるべきだという条件付きの道徳的命令。","行動の格律がそれ自体で普遍的な法則となりうるかを基準とした、無条件的な道徳的命令。","最大多数の幸福を実現するために、法や制度に従うべきだという社会契約的命題。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義が直面する「正義の直観」との対立を説明する例として、しばしば用いられる「トロッコ問題」の帰結について、功利主義者の立場からの解釈はどれか。', '["結果がいかなるものであっても、人を殺すという行為自体が不道徳であるため、レバーを引くべきではない。","一人の犠牲で五人の命が救われるならば、幸福の総量を最大化するためにレバーを引くべきである。","どちらの選択肢も非人道的であるため、行為者が選択を放棄することが唯一の正義である。","犠牲者の社会的地位や能力を精査し、より価値のある人物を救うべきである。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントの倫理学において「人間を手段としてのみならず、常に同時に目的として扱え」という定式が意味するものとして最も適切なものはどれか。', '["人間は社会全体の利益を増進するための有用な道具としてのみ価値を持つ。","個人の目的を達成するためであれば、他者を犠牲にしても道徳的に許容される。","いかなる状況下においても、人間を他者の利益を実現するための単なる道具として利用してはならない。","他者の幸福に寄与することが、自分の幸福を最大化するための唯一の手段である。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'J.S.ミルがベンサムの「量的功利主義」を修正し、「質的功利主義」を提唱した真意として正しいものはどれか。', '["幸福を計算する際には、快楽の強さよりも持続時間を重視すべきだと主張した。","低俗な快楽よりも知的な快楽の方が質的に価値が高いとし、幸福の多面性を認めた。","すべての快楽は等価であり、質的な区別は功利主義の本質を歪めると反論した。","快楽を求めることよりも、苦痛を避けることの方が人間にとって重要であると説いた。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '義務論の立場から、社会政策（例えば高額な医療費の負担）を考える際、最も重視される視点はどれか。', '["その政策がどれだけ多くの国民の税負担を軽減するかという経済効率性。","その政策が社会的な弱者を救済し、幸福の総量を最大化できるかという計算結果。","個人の生存権が、社会的な損得勘定とは無関係に、権利として担保されているかという点。","多数派の同意が形成されているかという民主的手続きのみを重視する視点。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義が民主的な法整備において強力な説得力を持つ理由として、最も適切なものはどれか。', '["個人の内面的な道徳律を極めて厳格に規定するため、規律が守られやすいから。","政策の効果を「幸福の総量」として客観的に比較・検証し、政策決定の論理的根拠を提供できるから。","歴史的な宗教的価値観をそのまま法制度として強制できるから。","少数者の利益を多数派の利益よりも常に優先させるという社会的正義に基づいているから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントの義務論において、行為の道徳的価値を決定する際の唯一の基準となるものは何か。', '["その行為がもたらす結果の有益性や幸福の増分。","行為者の道徳的義務感に動機づけられた「意志」の善性。","社会的な評判や賞賛が得られるかどうかという外的な評価。","最大多数の幸福という客観的な結果を達成できるかという成功の度合い。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会の生命倫理（安楽死や臓器移植など）において、功利主義的な考え方が引き起こす最大の懸念はどれか。', '["個人の意志を過度に尊重しすぎて、家族の同意が得られない場合に法的な混乱を招く点。","生命に優劣や有用性の尺度を適用することで、弱者の生存権が損なわれる危険性。","宗教的戒律に基づいた判断を強要し、科学的進歩を著しく阻害する点。","義務論的な制約が強すぎて、医療リソースの配分が不可能な状態に陥ること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「普遍的法則の原理」において、ある行動が道徳的であると認められるための条件は何か。', '["その行動をとることで、社会の経済成長が促進されること。","その行動の原理（格律）が、誰にとっても普遍的な法則となることを望めること。","その行動の結果として、周囲の人々が幸福を感じること。","その行動が特定のコミュニティの慣習や伝統に合致していること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベンサム流の功利主義に対する批判として、「正義の計算不能性」が指摘されることがある。これはどういう意味か。', '["幸福の総量を計算するための数学的手法がまだ確立されていないという技術的な問題。","人々の幸福や苦痛は質的に異なり、また個人の評価を客観的に数値化・比較することは不可能であるという点。","法律家が哲学を理解しておらず、計算結果を誤用しているという政治的な批判。","すべての人間が常に合理的に行動するとは限らないという心理学的な指摘。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントが「定言命法」を説く文脈で排除しようとした「仮言命法」とはどのようなものか。', '["目的が何であれ、とにかく無条件に従うべき道徳的な命令。","ある目的を達成するための手段として、特定の行動を命じる条件付きの命令。","人種や性別を問わず、全人類に対して等しく適用される絶対的な義務。","神の啓示に基づき、いかなる人間も背くことができない宗教的規定。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義と義務論の対立において、現代的な「人権」の概念が義務論と親和性が高いとされる理由は何か。', '["人権は幸福の最大化という結果次第で制限されるべきものだと規定されているから。","人権は目的を達成するための手段としてのみ認められるべきものだから。","人権は個人の尊厳に基づき、たとえ多数派の利益のためであっても侵害してはならないという絶対的な保護を求めるから。","人権は社会的な地位や功績がある者にのみ与えられる報償的な権利だから。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'J.S.ミルの「他者危害原則」について、功利主義の枠組みの中での位置づけとして適切なものはどれか。', '["国家は国民を幸福にするために、個人の自由をどこまでも制限すべきであるとする。","個人の行為は、他者に害を与えない限りにおいて最大限に尊重されるべきであり、それが長期的には全体の幸福を増進する。","他者に害を与えることは、義務論的な観点からのみ非難されるべきであり、幸福論とは無関係である。","個人の自由を完全に制限することが、社会の幸福を維持する唯一の道であるとする。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「多数者の専制」という概念は、功利主義に対するどのような危惧を表現したものか。', '["多数派が民主的な手続きで決定したことが、少数者の根本的な権利を蹂躙する結果を招く可能性。","少数のエリート層が多数の無知な大衆を支配し、不幸に陥れる社会構造。","幸福の総量を重視するあまり、社会全体が怠惰になり生産性が低下すること。","すべての決定を多数決で行うために、議論の時間が過剰にかかること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントにおける「自律」とは、どのような状態を指すか。', '["自分の欲望や衝動に従って、誰の干渉も受けずに自由気ままに生きること。","他者から押し付けられた法律や規範を、文句を言わずに受け入れること。","自ら道徳法則を立て、それに自分自身を服させるという理性的存在としてのあり方。","社会的な成功を目指して、自己の利益を最大化する手段を計画すること。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義の「平等」に対する考え方として正しいものはどれか。', '["各人の幸福の総量を等しく扱う（一人として数え、一人以上として数えない）という平等性。","すべての人が同じ結果（富や地位）を分け合うべきであるという結果平等主義。","個人の能力に応じて、より多くの幸福を与えられるべきだという能力主義的な平等。","特定の属性を持つグループの利益を、常に優遇すべきだという差別的な平等。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '義務論において、過失によって他者に損害を与えた場合、功利主義的判断と異なり重視されるのはどの点か。', '["損害を最小限に抑えるための事後の補償額が十分かどうか。","行為者が「善い意志」に基づいていたか、あるいは「義務」に違反したかという道徳的帰責性。","その過失が世間に対してどれだけのインパクトを与え、社会不安を惹起したか。","その過失を許すことで、将来的にどれだけの幸福が生まれるかという見通し。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義が現代の経済政策や公共政策において多用される理由として、最も適切なものはどれか。', '["人間を利己的な主体と仮定することで、市場原理に基づいた効率的な資源配分を正当化できるから。","すべての道徳的問題を絶対的な義務として解決しようとするから。","個人の感情や倫理観を排除し、宗教的価値観を政策の中心に置くことができるから。","少数者の権利を無視することが、民主的な社会を築くための唯一の手段だから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'カントの倫理が「厳格主義（冷徹）」であると批判されることがあるが、それはどのような理由によるものか。', '["結果的に誰かが不幸になろうとも、義務やルールを機械的に適用することを強いる側面があるから。","人々の幸福や感情を、一切の道徳的価値から排除しようとするから。","弱者の救済を禁じ、強者の論理のみを正当化しようとするから。","個人の自由を抑圧し、国家の命令に絶対服従を求めるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ジョン・ロールズが提唱した「無知のヴェール」において、原初状態にある人々が自己の社会的地位や能力を知らされない状況で合意する最大の理由は何か。', '["自分の有利な社会的地位を最大化するため","自分自身が社会の中で最も不遇な立場に置かれる可能性を考慮し、リスクを最小化するため","個人の自由競争を促進する効率的なシステムを選択するため","歴史的な伝統や慣習に基づいた正義を維持するため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズが批判した「自然的な自由の体系」における「機会の平等」の限界として、最も的確な指摘はどれか。', '["形式的な機会の平等だけでは、生まれ持った社会的・経済的条件による不平等が是正されないこと","能力主義を重視しすぎた結果、個人の努力を否定することになること","国家による経済介入が、個人の自由な経済活動を過度に制限すること","功利主義に基づき、少数者の権利が多数者によって侵害されること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの正義論において、「才能」や「家柄」といった偶然性を「共同の資産」とみなすべきだとする論理的背景は何か。', '["才能の差は個人の努力の結果であり、その成果を社会全体に分配すべきであるから","個人の能力や境遇は本人の努力以前の偶然的な運に左右されるため、個人の功績とみなすには道徳的根拠が乏しいから","国家が個人の才能を管理することで、生産性を最大限に向上させることができるから","市場原理を完全に廃止し、平等な配分を行うことが正義の唯一の形であるから"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズが提唱する「公正としての正義」において、自由と平等の対立が生じた場合に優先されるべきものは何か。', '["平等な社会的地位の獲得が、個人の自由よりも常に優先される","平等な自由の原理が、経済的利益や社会的地位の配分に関する原理よりも優先される","国家の経済成長を優先させるために、一定の個人の権利は制限されるべきである","多数決によって決定された方針が、いかなる個人の自由をも凌駕する"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '功利主義がロールズによって批判される最大の論拠はどれか。', '["功利主義は社会全体の幸福を重視しすぎるため、個人を単なる手段として扱い、個人の権利の独立性を軽視しているから","功利主義は個人の幸福を追求するあまり、社会全体の経済的効率性を損なっているから","功利主義は伝統的な道徳観念を重視しすぎるあまり、社会変革を阻害しているから","功利主義は無知のヴェールという思考実験を用いていないから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「公平な機会の平等」を達成するための現実的な施策として、ロールズ的な観点から正当化されやすいものはどれか。', '["恵まれない環境にある子供たちへの公教育や医療の無償化などの社会的投資","市場競争における規制を一切排除し、完全に自由な競争環境を整えること","高い能力を持つ者に税制優遇を行い、イノベーションを促進すること","家柄や財産に基づいた世襲制を強化し、長期的安定を図ること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの格差原理が、しばしば「パレート最適」の概念と対比して議論される理由は何か。', '["パレート最適は効率性を優先するが、格差原理は効率性よりも最悪の状況に置かれた者の底上げを優先するから","パレート最適は政府の介入を否定するが、格差原理は政府の介入を一切必要としないから","両者は全く同じ基準を提示しており、区別する必要がないから","格差原理は全市民の同一の配分を目指すが、パレート最適は多様な配分を許容するから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの正義論における「原初状態」の設定が持つ、倫理学上の意義として最も適切なものはどれか。', '["個人の特殊な事情や偏見を排除し、誰もが合意可能な公正な社会の基本原理を導き出すため","強者が弱者を支配するための正当な理屈を作り出すため","個人の欲望をすべて肯定し、市場競争を加速させる論理を提供するため","国家による強制力を正当化し、独裁政治を擁護するため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ノージックらリバタリアニズム（自由至上主義）の立場からロールズの格差原理を批判する場合、最も典型的な主張はどれか。', '["能力によって得た富を再分配のために課税することは、個人の自己所有権を侵害する強制労働に等しい","格差原理は社会の平等を過度に促進しており、さらなる経済的平等を求めるべきだ","格差原理は社会的弱者を軽視しており、福祉国家を強化する道につながっていない","無知のヴェールは現実の社会の複雑さを過度に単純化しすぎている"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会における「運の不平等」について、ロールズの思想を反映した考え方はどれか。', '["生まれ持った才能や境遇は本人の努力の結果ではないため、それが生み出す格差を社会の構造によって是正する必要がある","運の不平等は個人の努力によって克服できるため、政府の関与は不要である","運の良い人間を優遇することで社会全体が発展するため、格差を放置すべきである","才能の差は遺伝的要因がすべてであり、社会的な施策で修正することは不可能である"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「公平な機会の平等」において、教育的介入が強調される主な理由は何か。', '["教育が家庭環境による出発点の格差を軽減し、潜在能力を開花させるための媒介となるから","公教育によって国民の思想を統一し、社会の安定を図るため","労働力を効率的に分類・選別し、経済成長を促すため","教育の無償化が経済的な富の総量を増やす唯一の手段であるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの正義論において、「基本的自由」の例として適切ではないものはどれか。', '["言論および集会の自由","信教の自由","経済的な利益を最大化するために他者の権利を制限する自由","人身の自由および所有の自由"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの正義論の文脈で、「格差を是認する」ことが認められる条件として、正しいものはどれか。', '["その格差が社会全体の平均幸福量を最大化する場合","その格差が社会の最も不遇な人々の状況を改善する場合","経済的に強い者がさらに利益を得る権利が確保されている場合","格差があることで労働意欲が向上し、競争が活性化する場合"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズが提唱した「正義の二原理」における順序（辞書式順序）の意義として、最も適切なものはどれか。', '["第一原理である自由が優先され、第二原理の経済的配分は、第一原理が損なわれない範囲で許容される","経済的配分が常に優先され、自由はその次に調整されるべきである","両原理は全く対等であり、状況に応じてどちらを優先してもよい","第一原理を達成するためには、個人の自由を抑圧することが論理的に正当化される"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会における格差拡大の問題に対し、ロールズ的な観点から「ベーシックインカム」が議論される根拠として妥当なものはどれか。', '["すべての国民の最低限の生活を保障することが、公平な機会の前提条件となるため","市場競争の排除が労働意欲を完全に失わせることを検証するため","個人の能力や努力を無視した全平等社会を目指すため","ベーシックインカムが富裕層への課税を不要にする唯一の方法だから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの理論において、「社会的協力」を維持するための社会契約の必要性はどこにあるか。', '["社会は相互利益のための協働体制であり、その利益の配分において公正なルールが必要とされるから","社会は弱者が強者に保護される場であり、管理が必要とされるから","国家権力を維持するためには、国民を法によって厳格に支配しなければならないから","個人は孤立して生きるべきであり、社会契約はそのための独立を支援するから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの思想を大学入試小論文の論題として扱う際、最も論理的な対立軸となり得るのはどれか。', '["自由な競争を重んじる能力主義（メリトクラシー）と、結果の平等・公正を重んじる再分配論の対立","科学技術の発展と、伝統的文化の継承の対立","個人の心理分析と、マクロ経済の動向に関する分析の対立","宗教的道徳と、世俗的法治主義の対立"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '格差原理を巡る論争において、「インセンティブの確保」を主張する側の懸念は何か。', '["過度な再分配によって才能ある者の努力意欲が削がれ、結果的に社会全体の生産性が下がる可能性がある","格差原理は弱者救済を謳いながら、現実には政治家の利益誘導に使われるから","格差がなくなると、社会における競争そのものが消失し、文化が衰退するから","再分配を行うための行政コストが大きすぎ、結果的に誰も得をしないから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ロールズの正義論において、偶然性を排除した社会を目指すことの意味として、最も適切でない記述はどれか。', '["偶然に恵まれた者が、その富を無条件に独占し続ける状態を道徳的に否定する","個人の努力の価値を完全に無効化し、全員に一律の報酬を強制する","誰もがどのような境遇に生まれても、自らの人生を公正に追求できる条件を整える","社会的な地位や経済格差を、正当な根拠に基づいて論理的に説明可能な形にする"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'マイケル・サンデルが『実力も運のうち』において批判する「能力主義（メリトクラシー）」が内包する最大の道徳的弊害は何か。', '["個人の努力が軽視され、才能の不平等が固定化されること","成功者が自身の成功を単なる個人の努力の結果と捉え、運の寄与を忘却して傲慢になること","国家が能力開発のための公的資金を十分に投じないこと","市場原理が過度に強調され、技術革新が停滞すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが論じる「運の平等主義」の文脈において、現代の成功者が陥りがちな「傲慢」とはどのような心理構造を指すか。', '["自己の能力を過大評価し、他者からの批判を一切受け入れない心理","自らの社会的地位が個人の功績のみに由来すると信じ、敗者を不当な努力不足と見なす心理","過去の伝統や歴史的背景を無視し、革新のみを正義と見なす心理","自身の利益を最大化することのみを追求し、公共性を否定する心理"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義社会における「敗者」に対するサンデルの危惧として、最も適切なものはどれか。', '["敗者が自身の不遇を社会制度の不備であると強く確信し、政治的過激主義に傾倒すること","能力主義がもたらす経済格差によって、生存権が脅かされること","敗者が自らの置かれた状況を「努力不足」という自己責任論で内面化し、屈辱と自尊心の低下を強いられること","教育機会の格差によって、次世代への貧困の連鎖が不可避となること"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが提唱する「共通善（Common Good）」を追求する社会において、必要とされる態度はどれか。', '["個人の権利を制限し、国家による強力な中央集権的な分配政策を推し進める態度","自らの成功が多くの幸運に支えられていることを自覚し、連帯と謙虚さを持つ態度","市場経済における競争を可能な限り排除し、すべての人間が同一の報酬を得る態度","個人の功利主義的な目標達成を優先し、その過程で余剰利益を社会還元する態度"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義的な選抜制度（例：大学入試）が教育の場において「選別」以上の意味を持つという指摘の核心は何か。', '["大学入試が個人の知的能力を客観的に判定するための唯一の手段であるという信仰","教育が本来持つべき「善き市民の育成」という役割が、「社会的地位の獲得のための選別機」へと変質していること","公教育の質が低いため、家庭の経済力が結果を左右せざるを得ないこと","知識の価値よりも、学歴という記号的価値が社会全体で過大評価されていること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが指摘する「運の役割」において、彼が最も強調していることは何か。', '["努力そのものも遺伝や環境という幸運に左右されており、純粋な意志による功績は存在しないということ","どのような才能も、それが時代に評価されるかどうかは市場という偶然に依存しているということ","個人の能力を最大限に引き出すための社会的環境こそが、唯一の成功要因であるということ","運の悪さを社会が救済するシステムがあれば、能力主義は正しいと言えるということ"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義（メリトクラシー）という言葉の本来の否定的ニュアンスとして、社会学的に指摘されているものは何か。', '["能力主義は階級社会を打破する唯一の公正な理念であるという誤解","能力の測定には偏りがあり、真の能力が正しく評価されていないという不満","能力主義を極限まで追求すれば、それは「能力という名の新しい世襲制」へ変質しうること","能力が低い人間を排除することで、社会の生産性が著しく低下すること"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが指摘する「成功の物語」が政治的分断を招く理由として、最も適切なものはどれか。', '["成功者は自らの勝利を誇る一方で、労働者階級の功績を軽視し、連帯を分断しているから","成功者が政治権力を独占し、中低所得者の意見を政治の場から排除しているから","成功の物語が過度に楽観的であり、現実の不平等から目を逸らさせるから","成功者が地方都市の衰退を放置し、都心部への富の集中を促しているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「共通善」という概念の小論文的定義として、最も適切なものはどれか。', '["個人の自由を最大限に保障し、法の下の平等を追求する政治哲学","個々人が独立して自己利益を追求した結果、社会全体の利益が最大化される状態","社会全体の構成員が共に分かち合い、尊重し合うために必要な基盤や価値への配慮","多数決によって決定された、社会の安寧と平穏を維持するためのルール"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会における「学歴」と「尊厳」の関係性について、サンデルの立場から述べられた記述として正しいものはどれか。', '["高度な学歴が尊厳を保障するのは当然であり、学歴格差の是正よりも低学歴者の待遇改善を優先すべきである","学歴こそが現代社会における個人の尊厳を測る唯一の指標であり、学歴がない者は尊厳を持てない社会になっている","学歴が社会的地位だけでなく、人間としての価値の序列化に結びついており、これが尊厳の格差を生んでいる","学歴社会は解消に向かっており、今後は能力主義から人間性評価の社会へ移行するべきである"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが批判する「機会の平等」の限界とは何か。', '["機会の平等さえ達成できれば、結果の平等まで追求する必要はないという考え方","スタート地点を平等にしても、競争で勝った者による「敗者への支配」が正当化されてしまうこと","機会を平等にするためには、市場経済を否定しなければならないこと","機会の平等を声高に叫ぶ人々が、実際にはエリート層の世襲を支持していること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「労働の尊厳」を回復するためにサンデルが強調する視点として、誤っているものはどれか。', '["市場の評価だけで人間を判断せず、社会に貢献するあらゆる種類の労働を尊重する文化の醸成","高額報酬を得る仕事以外の職業に従事する人々に対し、感謝と敬意を忘れないこと","すべての労働者の賃金を一律に引き上げ、所得格差を完全に消失させること","市場価値が低いとされる労働であっても、その労働がコミュニティの維持にどう関わっているかを再認識すること"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義社会における「謙虚さ」の重要性について、サンデルは何と述べているか。', '["謙虚さは自己の成功を過小評価することであり、自信を失うリスクがあるため避けるべきである","謙虚さは他者への寛容を促し、私たちは偶然の恩恵を授かっているという認識に基づいた連帯を生む","謙虚さは個人の能力が低いという事実に直面した際にのみ必要となる処世術である","謙虚さは政治的な駆け引きにおいて相手を油断させるために必要な戦略である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義が「個人の責任」を過度に強調することの帰結として、最も懸念されることは何か。', '["社会保障制度に対する国民の信頼が強化される","成功者が寄付活動に精を出し、富の再分配が進む","社会構造的な要因（歴史、市場の偶然、家庭環境）が無視され、連帯感の欠如した社会になる","個人の自己研鑽意欲が高まり、国家全体の経済成長が加速する"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルの議論において、「市場原理」と「道徳」の関係はどうあるべきだとされているか。', '["市場は道徳的に中立であり、市場原理が道徳を決定すべきである","特定の価値観は市場の評価に委ねるべきではない領域があり、公的な議論によって共通善を定義すべきである","市場原理を完全に排除し、道徳のみに基づく計画経済への転換が必要である","道徳よりも市場の効率性を優先することが、結果的に最大の公共の利益にかなう"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代における「技術官僚的（テクノクラティック）な政治」とサンデルが批判する能力主義の共通点は何か。', '["専門的な知識を有するエリートが意思決定を行うことを最良とし、一般市民の熟議を軽視している点","市場原理を否定し、国家主導で平等な社会を設計しようとしている点","過去の伝統や宗教的価値観を重視し、技術革新を抑制しようとしている点","個人の能力よりも、集団の和と合意形成を最優先にしている点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが批判する「成功」の定義について、適切なものはどれか。', '["他者と協力してコミュニティの課題を解決することこそが、真の成功であるという視点","本人の努力と才能のみが成功を決定し、それを賞賛することは道徳的に正しいという視点","社会からの承認と経済的な報酬を得ることのみを成功と定義し、それ以外の価値を切り捨てる視点","運を味方につけ、リスクを最小限に抑えて資産を増やすことが成功であるという視点"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義的な思考がなぜ「他者への配慮」を妨げるのか。', '["他者は競争相手であり、配慮することは自分の成功を阻害する行為だから","能力主義を信じる人々は、他者の成功を運によるものだと考え、嫉妬を感じるから","能力主義は成功を「自業自得」の結果と見なすため、不運な人々に対する共感や連帯の必要性が感じられなくなるから","能力主義が定着すると、国家によるセーフティネットが充実し、個人の助け合いが必要なくなるから"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '能力主義の弊害を是正する手法として、サンデルが示唆している社会的な方向性はどれか。', '["試験制度の全面廃止と、抽選による大学入学者選抜の導入","市場で評価されない労働であっても、公共の利益に貢献する活動をより高く評価する社会への転換","所得の再分配を目的とした、富裕層に対する懲罰的な課税の強化","個人の能力評価の基準を、学力から身体能力や芸術的才能へと多様化すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'サンデルが主張する「運の平等主義」の究極的な目的は何か。', '["すべての人が等しい能力を持つ社会を実現すること","誰もが等しく運をコントロールできる社会制度を築くこと","成功が運に依存しているという事実を広く認め、成功者の傲慢さを退け、敗者の尊厳を守る公共的土壌を作ること","能力による序列を完全に破壊し、すべての人々が同一の職業に従事する社会を作ること"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代の公的年金制度における「賦課方式」が、将来世代への負担増を招く要因とされる論理的理由はどれか。', '["現役世代の保険料を積み立てて運用するため、市場リスクを次世代が負うから。","現役世代が納めた保険料を同時代の高齢者給付に充てるため、人口構成の変化が直接給付水準に影響するから。","年金給付額が個人の拠出実績とは無関係に、物価スライドのみで決定されるから。","賦課方式はインフレリスクを回避できるため、高齢層の購買力が過剰に維持されるから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「シルバー民主主義」が政策決定プロセスにおいて引き起こす最大の問題点は何か。', '["高齢者が生産活動に従事しなくなることで、経済成長が停滞する点。","高齢者の投票率が高く人口比でも多いため、政治家が将来世代よりも現役・高齢層の利益を優先する点。","民主主義の原理が否定され、権威主義的な政治体制へ移行するリスク。","社会保障給付が全て廃止され、市場原理のみで医療が提供されるようになる点。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会保障政策における「世代間公平性（ジェネレーション・エクイティ）」を検討する際、批判の対象となるのはどのような状態か。', '["現役世代が自らの教育投資を最優先し、社会保障費の負担を拒否している状態。","高齢世代が受給する給付総額に対し、生涯で支払った保険料・税の総額が著しく低い状態。","若年層の投票率が著しく低く、政治的な意思決定から排除されている状態。","社会保障制度が民営化され、自己責任原則が過度に強調されている状態。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '民主主義における「近視眼性（Myopia）」が、少子高齢化対策を困難にしている背景として最も適切なものはどれか。', '["政治家は短期的な選挙での当選を重視するため、効果の発現に数十年を要する構造改革よりも、目の前の有権者に利益を配分する政策を選択する傾向にあるから。","有権者が合理的な判断能力を欠いており、長期的な国家の損益を理解することが制度的に不可能だから。","議会制民主主義では長期的な計画を策定するための専門家集団を組織することが法的に禁止されているから。","少子化対策に必要な財源を確保するための増税が、憲法で禁じられているから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ジョン・ロールズの「正義論」に関連して、世代間倫理において「無知のヴェール」を仮定する場合、どのような合意が導き出されると考えるべきか。', '["自分がどの世代に生まれるか分からない状況であれば、現役世代の負担を極小化する制度を選択する。","自分がどの世代に生まれるか分からない状況であれば、どの世代に生まれても最低限の生活水準が保障されるような、世代間の公平な資源配分を選択する。","自分がどの世代に生まれるか分からない状況であれば、経済成長率を最大化するために社会保障を一切排除する制度を選択する。","自分がどの世代に生まれるか分からない状況であれば、富裕層に全負担を課す極端な累進課税制度を選択する。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会保障の「持続可能性」を問う議論において、「積立方式」の導入が検討される最大の意義は何か。', '["賦課方式に比べて運用利回りが確実に高く、経済成長を保証できるから。","個人の拠出額と給付額が直接結びつくことで、人口動態の影響を受けにくく、将来の給付水準を自律的に確保できるから。","国家が個人の資産運用を全面的に管理することで、国民の金融リテラシーを向上させることができるから。","積立方式に移行すれば、現役世代の負担が即座に消滅するため、社会不安が解消されるから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本において「少子高齢化」が社会保障制度の根幹を揺るがしている論理的帰結として、最も適切なものはどれか。', '["高齢者の数が増えることで、医療技術の飛躍的向上が阻害されるから。","社会保障費の増大が国の一般会計を圧迫し、教育や防衛など他の公共政策への資源配分を制約する（クラウディング・アウト）から。","人口が減ることで、労働力が不足し、結果としてデジタル化が完全に停止するから。","税収が減少することで、日本が国際的な主権を失うリスクが高まるから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「現役世代の負担増」を緩和するための政策オプションとして、専門家が議論する内容に合致しないものはどれか。', '["マクロ経済スライドの導入による給付額の自動的な抑制。","公的年金の支給開始年齢の段階的な引き上げ。","高齢者に対する医療費の自己負担割合の見直し。","社会保障制度を完全に全廃し、全ての国民が私的保険に加入することを義務付ける。"]', 3, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '民主主義の制度疲労に関連して言及される「ポピュリズム」が社会保障議論に及ぼす負の影響はどれか。', '["長期的な財政再建の重要性を訴えるよりも、高齢層の歓心を買うような給付維持・拡大を容易に主張してしまう点。","合理的な計算に基づく年金改革案を、あえて国民に提示しない点。","全ての国民に平等な参政権を付与するため、決定までに時間がかかりすぎる点。","政治的対立を回避するために、野党の意見を全て取り入れてしまう点。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「社会連帯」の概念を社会保障の文脈で解釈した場合、どのような原理を指すか。', '["血縁や地縁がある者同士で助け合う、家族主義的な互助精神のこと。","国家が介入せず、市場で稼いだ者が自己責任で社会を支えること。","同時代に生きる人々が、リスクを共有し支え合うという考え方（水平的連帯）に加え、世代を超えて責任を分かち合う考え方（垂直的連帯）。","一定の所得がある者だけが、貧困層を保護するための慈善活動を行うこと。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '将来世代への「ツケ回し」という表現が批判的に指し示しているものはどれか。', '["現役世代が将来の年金受給のために行っている個人の貯蓄行為。","政府が現在の歳出をまかなうために国債を発行し、その償還義務を将来の税負担に転嫁している現状。","過去の世代が残したインフラを維持管理するために必要な修繕コスト。","若年層が現在の社会保障を維持するために進んで納めている高い保険料。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「自助・互助・共助・公助」というフレームワークにおいて、少子高齢化で公助の限界が指摘される中、何を強化すべきという議論が一般的か。', '["公助をより拡大し、全ての生活を国家が補償する体制への回帰。","公的な福祉サービスを排除し、完全な自助のみによる社会システムの構築。","家族や地域コミュニティ（互助）の再生や、個人の就労と自助努力の促進。","国際機関による国家への財政的支援の要請。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「人口ボーナス」の時期と対比して、「人口オーナス」の社会で直面する最大の課題はどれか。', '["生産年齢人口の割合が低下し、経済全体の活力が失われる中で、社会保障費が膨張する構造。","労働者が不足することで、賃金が極端に上昇し、企業の利益が確保できなくなること。","人口が減ることで、都市部への過度な集中が解消され、地方が活性化しすぎてしまうこと。","高齢者が多いことで、イノベーションが加速し、技術が成熟しすぎること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会保障の持続可能性を考える際、しばしば「世代会計（ジェネレーショナル・アカウンティング）」という手法が用いられる理由は何か。', '["現役世代の平均年収を正確に把握することで、個人の所得格差を解消するため。","将来世代が一生涯に支払う税・社会保険料と、受け取る給付の差額を算出することで、現役・将来間の不公平さを可視化するため。","高齢者の投票率と若年者の投票率を比較し、選挙結果を予測するため。","各年代の消費行動を分析し、景気対策に役立てるため。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「受益と負担の均衡」という観点から見た場合、現在の年金制度において最も議論になりやすい論点はどれか。', '["若年層が将来受給できる年金額に対して、支払う保険料の総額が投資効率として極めて低いという「世代間の不公平」。","高齢者が受け取る年金額が、過去の物価変動を考慮していない点。","保険料の徴収が、高所得者に偏っている点。","年金運用の失敗が、年金受給額に全く影響を与えていない点。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「社会保障の自然増」とはどのような現象を指すか。', '["国民の意識が高まり、進んで保険料を納めるようになること。","高齢化の進展や医療の高度化に伴い、制度を改正しなくても自動的に支出が増加していくこと。","景気の変動に合わせて、自動的に税収が増加すること。","出生率の上昇により、自動的に社会保障を支える若者が増えること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '民主主義の欠陥として指摘される「独裁の回避」と「長期的な意思決定」の両立について、有効な対策として議論されるものはどれか。', '["国民投票を頻繁に行い、全ての政策を国民の直接的な意志で決めること。","将来世代の利益を代表する枠組み（例えば将来世代のためのオンブズマンや議会への諮問機関）の設置。","世襲制の政治家を増やすことで、政策の連続性を確保すること。","選挙を廃止し、専門家による評議会が全てを決定するテクノクラート支配。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「賦課方式」の維持を主張する論者が見出す、社会的な効用は何か。', '["市場運用を行わないため、リーマンショックのような金融危機の影響を受けないこと。","若者が高齢者を支えるという社会的な相互扶助関係が可視化され、連帯感が醸成されること。","インフレが起きると、年金給付額が自動的に減額されるため、国の財政を守れること。","将来の人口減少に関係なく、常に現役世代の負担を一定に保てること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '少子化の原因を「社会構造的な要因」として捉える際、最も重視される視点はどれか。', '["若者の個人の努力不足や、結婚に対する価値観の変化のみ。","長時間労働、雇用形態の不安定化、保育インフラの不足など、子育てを選択しにくい環境的制約。","人口が自然に減少することこそが、環境負荷を減らすために必要だという考え方。","遺伝的な要因により、子供を持ちたいと思う若者が減少しているという事実。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「世代間の合意形成」を促進するために、小論文等で提言される概念として適切なものはどれか。', '["高齢者の発言権を完全に剥奪し、若年層の意志を優先する政治システム。","世代間で負担と給付の構造を冷静に議論するための、客観的なデータに基づく対話の場の構築と教育。","年金制度を廃止し、全ての国民が自らの資産で老後を賄うという完全なる自己責任論の強制。","政府が一方的に将来の負担増を決め、国民の合意を仰がないトップダウン方式。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '伝統的な家族観において、家族は「私的領域」として社会保障の補完的役割を担ってきた。現代日本において、この「家族依存型福祉モデル」が限界を迎えている最大の要因として、最も適切なものはどれか。', '["世帯所得が世界的に見て高水準で安定しているため、個人の依存心が強まったから","少子高齢化と世帯構造の変化により、家族による介護・扶養という無償労働の提供が不可能になったから","個人の自立を尊重するリベラリズムが広まり、国家による公共サービスが過剰に拡充されたから","離婚率の低下により、世帯あたりの扶養人数が増大したから"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ヤングケアラー」が社会問題化する背景として、ケアの外部化や公共サービスの活用が遅れていることが指摘される。この問題の構造的課題として最も妥当なものはどれか。', '["ケアは家庭内で行われるべきという「私的領域の神話」が根強く、公的な介入が家族の絆を損なうと見なされる傾向があるから","子どもが家族の世話をする行為は道徳的に称賛されるべきであり、ケアの労働化は教育的観点から不要であるから","ヤングケアラーの家庭は経済的に困窮しているため、福祉サービスへのアクセスにコストがかかりすぎることが唯一の阻害要因だから","子どもにはケアを行う能力が全く欠如しており、社会がその事実を隠蔽しているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '選択的夫婦別姓制度の導入をめぐる議論において、反対論の根拠として頻繁に提示される「家族の絆」に関する論理として、適切なものはどれか。', '["同一の氏を名乗ることで家族の一体感が保持され、社会的な連帯の基盤が強固になるという伝統的価値観に基づく主張","氏が異なると法的に親子関係が認められず、相続権が消失するため、経済的不安定を招くという法的解釈に基づく主張","選択的夫婦別姓が導入されると、すべての国民に強制的に別姓が課され、戸籍制度が崩壊するという帰結主義的主張","夫婦が別姓を選択することは、個人のアイデンティティを完全に消滅させ、公的なコミュニケーションを不可能にするという社会学的分析"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「無縁社会」における「孤立死」の増大は、都市部におけるどのような社会的変容と関連しているか。', '["地縁・血縁といった中間集団の解体と、個人のプライバシーを過度に尊重する社会規範の浸透による関係性の希薄化","デジタル技術の発展により、物理的な距離に関係なく誰もが密接なつながりを構築できるようになったことの副作用","都市部への過度な一極集中によって、地域住民同士の相互監視が強化され、プライバシーが侵害されていることによる反動","社会保障が過剰に充実した結果、他者の助けを必要としない自立した個人が増大したことによる結果"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ケア労働の社会化とは、従来家族（特に女性）が無償で行ってきたケアを、専門職や公的サービスに移転することを指す。この転換が求められる経済的・倫理的理由として最も適切なものはどれか。', '["女性の社会進出による労働力確保の要請と、ケアを個人の自己責任から公共の責任へと再定義し、ジェンダー平等を推進する必要があるから","家族によるケアは極めて非効率であり、機械化・自動化が可能な看護や介護のみを推進することで社会の生産性を劇的に向上させるため","ケアの質は専門家よりも家族の方が常に高いことが証明されており、コスト削減のために専門職の関与を排除すべきだから","労働者不足を解消するために、全てのケア労働を完全に無償ボランティアへと転換し、国家予算を削減する必要があるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「孤独・孤立」を単なる個人的な問題ではなく、構造的な社会課題として捉えるべき理由として、最も妥当なものはどれか。', '["孤独は感染症のように人から人へ広がるものであり、精神医学的な治療を行わなければ社会の生産性が低下するから","現代社会の労働環境や地域構造、福祉の隙間が個人を孤立に追い込んでおり、個人の努力のみでは回避困難な要因が介在しているから","孤独な人は他者に危害を加える傾向が極めて高いため、国家の治安維持の観点から徹底的な監視が必要だから","孤独こそが人間関係の究極の完成形であり、その状態を強制的に作り出すことが近代国家の究極の目的であるから"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '家族の多様化が進む中で、「家制度」に基づいた法制度（戸籍等）が抱える論理的矛盾として、最も適切なものはどれか。', '["同性婚や事実婚などの新たな家族形態が法的に保護されず、既存の「世帯単位」の福祉給付から排除されるケースが生じていること","家制度がすでに憲法で禁止されているため、戸籍そのものが存在せず、日本社会は法的な家族観を完全に喪失していること","すべての国民が個別の個人として登録されており、家族という概念そのものが戸籍法から完全に消失していること","家制度が現代の経済成長を強力に促進しており、個人の自由を制限することが経済的に最適であること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ケアを「個人の義務」とする考え方から「社会的な権利」とする考え方への転換において、鍵となる概念はどれか。', '["ケアの質を家族の愛着にのみ依存させ、公的な介入を最小限に抑える「ケアの私有化」","人間が相互に依存し合っている存在であることを前提とし、ケアを公共的インフラとして提供する「ケアの倫理」","自立した強固な個人のみが尊厳を持つという前提に基づき、ケアを受ける者を社会の負担とみなす「自己責任論」","ケア労働は対価を払うべきではないという伝統的道徳観を強固にし、ボランティア精神を強制する「徳育の再興」"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本における「選択的夫婦別姓」の反対派が、改姓によって生じるメリットとして強調しがちな観点はどれか。', '["改姓により個人のアイデンティティが統合され、自己決定の自由が飛躍的に増大するという主張","夫婦同一の氏を名乗ることで生じる社会的な記号としての家族の一体感や、伝統的な呼称の継続性","別姓を選択することで、離婚率が下がり、社会全体の安定性が増すという統計学的なエビデンスに基づく主張","氏が同じであることが、憲法上保障された唯一の婚姻形態であるという絶対的な法的解釈"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「社会的孤立」が顕在化した現代において、地域コミュニティが再評価されているが、その際注意すべき「共同体の負の側面」とは何か。', '["地域住民同士の過度な相互監視や同調圧力により、個人の自律性やプライバシーが阻害される可能性","地域コミュニティがデジタル化しすぎており、高齢者が参加できないという物理的障壁","コミュニティが経済活動を一切行わないため、かえって地域の経済が活性化してしまう点","共同体への参加が義務化され、日本国憲法が保障する「結社の自由」が完全に廃止される点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代日本社会における「自立」の定義を再考する際、正しい捉え方はどれか。', '["他者の助けを一切借りず、自分ひとりの力で生活を完結させることこそが、成熟した大人のあり方である","「孤立すること」と「自立すること」を混同してはならず、必要な時に他者と繋がり、助けを求めることもまた自立の一部である","自立とは経済的な成功のみを指す言葉であり、精神的な健康や対人関係の豊かさは自立の定義には含まれない","若年期には家族に完全に依存し、高齢期になって初めて自立を目指すというライフコースが現代の理想である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ケア労働の社会化を推進する際の経済的なジレンマとして、最も適切なものはどれか。', '["ケアを公的サービスに委ねると、サービス提供に伴う財源確保（増税等）と、質の維持という両立困難な課題が生じること","ケアを社会化すると、家族間の絆が強まりすぎてしまい、子どもが親を介護することに抵抗を感じなくなること","ケアが社会化されると、労働者がケアの仕事に殺到し、人件費がゼロになるという経済理論上のパラドックス","ケア労働が完全に自動化されることで、労働者が一切の対人コミュニケーションを行う必要がなくなる点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会において「家族の多様化（事実婚、同性カップル、単身世帯の増加等）」が進む理由として、最も適切なものはどれか。', '["伝統的な家族モデルを維持することが経済的・社会的にコスト高となり、個人のライフスタイルや価値観の多様性を重視する傾向が強まったから","法律によって伝統的な家族以外の形態が強制的に推奨されるようになったから","少子化を加速させるために、国家が意識的に家族を解体する政策をとっているから","家族を構成する意欲が人類から完全に消失したから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ヤングケアラーに対する支援において、「ケアの当事者性」を認めることが重要であるのはなぜか。', '["子どもがケアを担っているという事実を否定することで、問題そのものが消滅し、家族の平和が守られるから","当事者が抱える特有の困難（学習機会の損失、精神的負担等）を可視化し、適切な公的介入を行うための出発点となるから","すべての子どもに強制的に介護を義務付けることで、社会全体の奉仕精神を育成できるから","ケアを行っている子どもこそが、将来の福祉政策を決定する唯一の権利者であるとみなされるから"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '日本の少子化対策において、単に金銭的な給付だけでは不十分だという議論がある。その背後にある、「家族のケア規範」に関する問題点は何か。', '["性別役割分業意識が根強く残存しており、育児・ケアが主に女性に偏っているため、制度を整えても利用しにくい構造があること","金銭的な支援が過剰であり、人々が働かずに家族と過ごすことばかりを優先するようになったこと","家族という単位を一切考慮せず、個人の生活のみを支援しているため、かえって家族の絆が深まりすぎていること","日本には家族を支援するという文化が全く存在せず、他者との助け合いが禁じられていること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「無縁社会」が引き起こす政治的な課題として、正しいものはどれか。', '["社会的な絆を失った個人は投票行動を放棄する傾向があり、民主主義の正当性や政治的合意形成が危うくなる点","孤立した個人が政治に関心を持ちすぎると、国家の転覆を企てる可能性が高まる点","住民同士の交流がなくなることで、逆に治安が向上し、警察の必要性がなくなる点","社会的な繋がりがない人ほど、高い税金を負担するようになるため、経済格差が是正される点"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ケアの倫理」において、人間を「傷つきやすく、相互に依存し合う存在（依存性）」として捉える意義は何か。', '["自立を唯一の善とする近代的な人間像を見直し、他者とケアし合う関係性そのものを社会の基盤として評価できるから","人間は機械のように効率的に動くべきであり、依存は排除されるべき非効率な要素だと結論づけられるから","依存を容認することで、すべての人間が社会の寄生虫として生きることを肯定できるから","ケアという行為を、個人的な奉仕活動の枠内に留めるべきだと強調するため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会の「個人の自立」に関するパラドックス（逆説）として、最も妥当なものはどれか。', '["過度な個人の自立を追求することでかえって孤立を招き、結果として他者からのケアを必要とする事態が生じること","自立しようとすればするほど、経済的に裕福になり、誰の助けも必要としない絶対的な支配者に変貌してしまうこと","自立を教育の目標に掲げることで、誰もが他者の意見に流されず、絶対的な自己主張を行うようになること","家族に依存している人間ほど、社会的に孤立しており、地域コミュニティとの繋がりが強いこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '選択的夫婦別姓議論において「夫婦が同一の姓を名乗るか否か」が、なぜこれほどまでに家族のあり方と結びつけて議論されるのか。', '["氏（姓）が、単なる呼称を超えて、日本社会における家族の共同体性や家父長制のシンボルとして機能しているから","氏が異なると、婚姻関係そのものが法律上無効であると民法が規定しているから","改姓をしないことは、他者に対する明確な敵意の表明であると法的に定義されているから","すべての日本人が氏を変更することに対して強い心理的抵抗感を持っており、それが国家の安定に直結しているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '社会的孤立対策としての「つながり」の再構築において、行政が行うべき役割として最も適切なものはどれか。', '["個人の人間関係に直接介入し、誰と交流すべきかを命令すること","孤立しがちな層が安心して交流できる場や相談体制を整備し、支援の手が届くインフラを整えること","地域住民全員に週に一度の強制的な交流イベントを義務付けること","孤立を「個人の自由」として放置し、一切の介入を断つことが行政の究極の福祉政策であるとする姿勢をとること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'デヴィッド・グレーバーが提唱した「ブルシット・ジョブ」の定義として、最も適切なものはどれか。', '["賃金が市場価値に見合わない低水準である労働","高度な専門知識を要するにもかかわらず、社会的地位が低い労働","その職務に従事する本人でさえ、存在意義や必要性を感じられず、組織の官僚的慣習によって維持されている無意味な雇用形態","AI技術の発展により、将来的に確実に代替されることが予測される非効率な反復作業"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会における報酬体系の矛盾として、いわゆる「エッセンシャル・ワーカー」の待遇が低い主な要因はどれか。', '["彼らの労働が市場経済において高い生産性や付加価値を生み出しにくいと評価される傾向にあるから","教育訓練に要するコストが過大であり、参入障壁が低いため","彼らの労働は非市場的価値が高いため、貨幣的評価が困難であるから","法規制によって報酬の上限が厳格に定められているから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベーシックインカム（UBI）導入に対する保守派・経済自由主義的立場からの主な懸念や論理はどれか。', '["社会保障費の削減により、行政の肥大化が加速するため","無条件の現金給付が、勤労のインセンティブを削ぎ、自律的な市民形成を阻害するため","富の再分配が進むことで、資本主義の根幹である私有財産制が否定されるため","労働需要が不足している状況下では、インフレ率が過度に抑制されるため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '労働を「自己実現の手段」と見なす人間観と、ブルシット・ジョブが蔓延する現状の乖離を説明する論理として最も妥当なものはどれか。', '["労働は生存のための義務であるという古典的経済学の前提が、現代の豊かな社会において完全に無効化したため","企業が労働者を監視・統制するために、真の目的とは無関係な管理職や事務職を創出する動機を持つため","技術革新により労働時間が短縮された結果、労働の価値が相対的に低下したため","個人の選択権が拡大し、誰もがやりがいのある職種を選べるようになった結果、無意味な仕事が淘汰されたため"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベーシックインカム導入の経済的メリットとしてしばしば提示される「既存の社会福祉制度の整理・統合」が目指すものは何か。', '["低所得者層への手厚い保護を廃止し、富裕層への減税を行うこと","複雑な受給要件や管理コスト（行政コスト）を削減し、政府の効率性を高めること","公的な教育・医療サービスを民営化し、すべて市場原理に委ねること","国境を超えた同一労働同一賃金を達成するための基盤を整えること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「労働」を価値の源泉とみなすマルクス主義的労働価値説の観点から見て、ブルシット・ジョブの存在はどのように解釈されるか。', '["余剰価値を生まない労働は資本家によって即座に排除されるため、理論的に存在し得ない","労働の疎外が極限に達した結果、労働が本来の「生存の手段」から離れ、支配と服従の形式に陥ったもの","労働者が自らの意思で労働を選択した結果であり、自由な市場経済の帰結である","生産力の上昇に伴い、労働の苦痛が軽減された過渡的な現象である"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ユニバーサル・ベーシックインカムが「雇用の流動化」を促進するという議論の背景にある考え方はどれか。', '["最低限の生活が保障されることで、労働者が不当な労働環境から離脱し、より創造的で条件の良い労働を選択しやすくなるため","失業保険制度を全廃することで、企業側が解雇を行いやすい労働市場が形成されるため","個人の所得が均一化されることで、地域間の所得格差が解消され、移動コストが低下するため","全ての国民が起業することを前提とするため、既存の雇用契約が解体されるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「労働の将来」に関する議論において、AI・自動化技術の進展がブルシット・ジョブに与える影響として最も可能性が高いと論じられるのは何か。', '["無意味な仕事が全て自動化され、人類は完全に労働から解放される","本来、自動化が可能なはずの「非創造的で官僚的なルーチンワーク」こそが、組織の権力維持のために人間によってしがみつかれるようになる","AIの管理コストが人間を上回るため、結果として人間の雇用が増大する","AIが創造性を代替することで、人間は事務処理などの単純作業に専念せざるを得なくなる"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'エッセンシャル・ワーカーの待遇改善を議論する際、「社会的有用性」と「市場価格」の乖離を解消するために提案される手段として適切でないものはどれか。', '["労働組合の再編による団体交渉権の強化","最低賃金の法的な抜本的引き上げ","当該職種に対する政府の公的助成や賃金補填の導入","市場競争原理を極限まで働かせ、価格決定を完全に市場に委ねる"]', 3, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「労働神話（労働は無条件に善であるという信念）」が社会政策の決定に与える影響についての記述として、最も適切なものはどれか。', '["労働の尊さを強調することで、失業者の自己責任論が強化され、ベーシックインカム導入の障壁となる","労働を通じてのみ富が創造されるため、どのような労働も等しく高く評価される社会が実現する","労働の価値が過大評価されることで、AI導入が進まず技術革新が停滞する","労働を重視する姿勢は、ジェンダーによる役割分業を解消する強力な根拠となる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会における「労働の疎外」の文脈で、ブルシット・ジョブが個人に与える心理的影響を最も適切に説明しているのはどれか。', '["過酷な労働環境により、身体的な疲労と病気が慢性的になる","自らの貢献が実質的に何も生み出していないという自覚が、自己尊厳の喪失や虚無感を生む","生産性を追求しすぎることで、家族や地域コミュニティとの繋がりが強化される","創造的な仕事に従事することで、個人の能力が最大限に発揮される"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベーシックインカムの反対論として「財源問題」が挙げられる際、最も深刻な懸念として指摘されるのは何か。', '["給付金が少なすぎて貧困が解消されないという懸念","高額所得者からの徴税を増やすと、労働意欲が減退し、国家全体の生産性が低下するという懸念","給付金が仮想通貨市場に流れ込み、経済バブルが起きる懸念","行政のIT化が遅れているため、配布コストが過大になる懸念"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「エッセンシャル・ワーカー」という言葉が持つ、現代の価値観における二重性を説明したものはどれか。', '["経済的に極めて高給である一方で、社会的な評価は著しく低いという矛盾","社会の存続に不可欠な存在であると承認されつつも、経済的・社会的な待遇は低いという現実","過去においては尊敬されていたが、現在はAIに置き換えられつつあるという歴史的変遷","本人の自尊心は高いが、企業からはコスト削減の対象として見なされているという構図"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ブルシット・ジョブ論が、現代の資本主義社会における「企業の目的」についての問いをどのように変容させたか。', '["企業は利益の最大化のみを目指す純粋な経済主体であるという認識を強化した","企業は生産性のみならず、雇用を生み出すこと自体を絶対的な目的とするようになった","企業の肥大化が必ずしも効率的な経済活動とは限らず、管理の複雑化こそが非効率を生むことを示した","企業こそが個人の生きがいを創造する唯一の公共機関であることを証明した"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「労働の質」の低下が叫ばれる一方で、一部の職種が「意味のある仕事」として崇拝されることの弊害として適切なものはどれか。', '["意味ある仕事に従事する人々の給与が抑えられること","それ以外の職種に就く人々の自尊心を傷つけ、分断を深めること","社会全体が過剰に教育水準を求めるようになり、失業率が上昇すること","すべての職業の定義が不明確になり、市場経済が崩壊すること"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ベーシックインカムが提示する「脱労働」社会というビジョンが、市民にとっての自由を再定義する側面はどれか。', '["労働から完全に離れることが、唯一の理想的な自由の形であるという主張","経済的な生存の保障を前提とすることで、従属的な労働契約に縛られない「選択の余地ある自由」の拡大","市民の自由を奪い、すべての個人が国家に従属することを強制する仕組み","労働時間を完全に撤廃し、全員が同時に余暇を楽しむ権利の確立"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '労働と報酬の乖離が拡大する中で、「社会的有用性」を客観的に評価する際の困難さはどこにあるか。', '["有用性は主観的であり、貨幣的価値とは異なる基準（ケア、環境、芸術など）で測定されるべきであるが、既存のGDP指標には反映されにくいから","政府がすべての職種の価値を法的に固定しているため、市場の調整機能が働かないから","有用性は労働者の学歴によってのみ決まるため、統計上の誤差が大きいから","有用性を算出するための計算式が、グローバルな金融市場で公開されていないから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ポスト・ワーク（労働後）」社会の議論において、ベーシックインカム以外に検討される代替的解決策として最も一般的なものは何か。', '["労働時間の劇的な短縮（週3日制など）による労働のシェアリング","全企業を国営化し、全国民を公務員として雇用する体制","すべての教育機関を廃止し、徒弟制度による技術継承への回帰","国内の全物流をロボット化し、人間は娯楽のみに専念する社会"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ブルシット・ジョブの問題を論じる際、なぜ「官僚的」という言葉が批判の対象として多用されるのか。', '["公務員だけが意味のない仕事をしているという偏見を助長するため","階層化された組織内部で、本来の目的を達成することよりも、手続きを維持すること自体が自己目的化する傾向を指すため","民間企業には官僚的な仕事は存在せず、すべて行政の責任であると強調するため","グローバル経済において、官僚組織が最も生産性が高いから"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会において「労働の意味」を問い直す際、最も留意すべき倫理的な視点は何か。', '["労働者の収入がどれだけ多いかという絶対的評価軸","職業的アイデンティティが個人の人格形成に与える影響と、労働による疎外・搾取とのバランス","技術の進歩がいかにして労働者の肉体的負担を減らしたかという歴史的進歩史観","いかにして国民全員を雇用することで、国家の税収を安定させるかという財政的視点"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ポスト真実（Post-truth）」という用語が示唆する、現代社会の最も本質的な変容とは何か。', '["科学的客観性が完全に否定され、すべての知が相対化された状態","客観的事実よりも、個人の信条や感情への訴えかけが世論形成において優位に立つ現象","政府による情報統制が強化され、事実の歪曲が公然と行われる政治体制","デジタル・ディバイドにより、真実へのアクセス権が格差を生んでいる状況"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「フィルターバブル」現象が民主主義の健全な議論を阻害するメカニズムとして最も適切なものはどれか。', '["アルゴリズムが個人の嗜好に合わせて情報を選択的に提供し、異なる意見に触れる機会が遮断されること","匿名掲示板等で、特定の個人が集中的な批判にさらされ沈黙せざるを得なくなること","情報の氾濫により、人々がどの情報が真実であるかを判別できず、議論を放棄すること","公的機関の情報提供が不足し、市民が誤った情報に基づく判断を強いられること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「エコーチェンバー」現象において、閉鎖的なコミュニティ内で特定の言説が先鋭化していく心理学的要因はどれか。', '["新しい情報を常に求める知的好奇心と、多面的な視点への敬意","集団内で似た意見が反復されることで、その意見がより強固かつ過激な確信へと変容する過程","外部からの批判に対して、冷静かつ論理的に対抗しようとする防衛本能","多様な情報源から得た知見を総合し、中立的な立場を維持しようとする志向"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代のSNS空間において「確証バイアス」が果たす負の役割として、最も妥当なものはどれか。', '["自説を補強する情報ばかりを無意識に選択し、自分に都合の悪い事実を無視・矮小化してしまう傾向","複数の視点を比較検討した結果、最も合理的な結論を導き出す知的な過程","他者の意見を全面的に受け入れ、自分自身の主体的な判断を放棄する心理状態","論理的な整合性を重んじるあまり、感情的な訴えかけを過度に拒絶してしまう態度"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '公共圏（パブリック・スフィア）の再建を議論する際、ハーバーマスのいう「コミュニケーション的理性」が現代において直面している困難はどれか。', '["対話を通じて相互理解を目指す前提となる『共通の事実認識』が揺らいでいること","情報通信技術の発展により、誰でも自由に発言できる環境が完全に整備されたこと","国家が公共空間における議論のルールを厳格に定義し、統制していること","市民の教育水準が低下し、高度な論理的議論を理解できなくなっていること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'フェイクニュースが人々の間で急速に拡散する背景にある、情報消費者の態様を何と呼ぶか。', '["情報リテラシーの極度な向上と、批判的思考の常態化","事実の正確性よりも、驚きや怒りなどの感情を喚起する情報の共有を優先する態度","情報提供者の政治的背景を常に調査し、中立性を検証しようとする慎重さ","長文の解説記事を精読し、背後にある社会的文脈を理解しようとする姿勢"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「プラットフォームによるアルゴリズムの透明性」が議論の焦点となる理由は何か。', '["ユーザーが自身の思考や行動がプラットフォーム側によって操作されている可能性を懸念するため","すべてのプラットフォームが政府によって管理されるべきという法的な合意があるため","広告収益よりも情報の真偽を優先することが経済的に合理的であると証明されたため","AIの判断が常に人間よりも倫理的に正しいと認識されているため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '民主主義における「寛容」のパラドックスとはどのような状況を指すか。', '["民主主義を守るために、民主主義を破壊しようとする不寛容な言説をも許容すべきかというジレンマ","他者の意見を尊重しすぎて、自らの信念を一切主張できなくなること","多様な価値観を認め合う社会ほど、法による統治が不要になるという考え方","言論の自由を制限することが、結果として言論の自由を守る唯一の手段であるという主張"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'デジタル時代における「分極化（ポーラリゼーション）」の進展が、政策決定に及ぼす影響として最も考えられるものはどれか。', '["合意形成のための妥協や対話が困難になり、政治の停滞や社会的亀裂が深まる","多様な意見が統合され、より迅速で柔軟な合意形成が可能になる","国民全体の政治への関心が高まり、投票率が劇的に上昇する","対立する陣営が相互理解を深め、より包括的な政策が立案されるようになる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ナラティブ（物語）」が政治的説得において強力なツールとなる理由は何か。', '["論理的整合性よりも、人々の直感的な理解を促し、帰属意識や感情的共鳴を生みやすいため","膨大な統計データに基づき、政策の客観的効果を証明できるため","歴史的な事実をそのまま継承し、教育の場で客観的に語り継がれるため","どのような政治的主張に対しても、一貫した中立性を保つことが可能だから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ミディスインフォメーション」と「ディスインフォメーション」の決定的な違いは何か。', '["悪意の有無であり、意図的に騙すものがディスインフォメーション、悪意なく誤情報を拡散するのがミディスインフォメーション","拡散される媒体の違いであり、SNSが前者を、新聞が後者を担う","情報の新旧の違いであり、最新のものがディスインフォメーションである","発信者の社会的地位による違いであり、権力者が発信するか否かによる"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会において「デジタル・リテラシー」教育が喫緊の課題とされる最大の目的は何か。', '["情報の取捨選択能力や真偽の検証能力を高め、情報環境の罠に自律的に対処する力を養うこと","インターネット上の誹謗中傷を完全に根絶し、快適なオンライン空間を維持すること","政府が推奨する情報を素直に受け入れ、国民の団結力を強化すること","すべての国民がプログラミングの基礎を習得し、デジタル経済の発展に寄与すること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ハンナ・アーレントが提唱した「事実の喪失」が現代の政治に示唆していることは何か。', '["客観的な事実が政治的論争の具にされ、誰もが合意できる共通の地盤が失われる危うさ","政府がすべての事実を公開することで、国民の不信感が増大する現象","事実を知る必要はなく、信念のみが政治を行うための唯一の手段であるという考え","メディアが事実を追求するのをやめ、娯楽の提供に専念すべきであるという主張"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'アルゴリズムによる「コンテンツのレコメンデーション」がもたらす「知の囲い込み」とはどのようなものか。', '["ユーザーの関心領域に適合する情報ばかりが供給され、未知の知見との遭遇が組織的に阻害されること","知識の断片化が進み、学術的な専門性が高まりすぎて社会全体で共有できなくなること","情報の有料化が進み、富裕層しか質の高い情報にアクセスできなくなること","国境を超えた情報の流通が制限され、各国の文化が孤立していくこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代の選挙戦においてSNS広告のターゲティング技術が民主主義の脅威となりうる主な理由は何か。', '["マイクロターゲティングにより、個別の有権者の不安を煽る情報をこっそり提示でき、公的な議論が成立しなくなるため","広告がすべての人に同じ内容で届くため、意見の多様性がなくなるため","広告の費用が安価すぎて、候補者の資金力が無意味になるため","SNS広告が法的に完全に禁止されており、選挙活動が不可能になるため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「ファクトチェック」の役割が限定的なものにとどまることがある理由として、最も適切なものはどれか。', '["真実が示されても、既に強い信念を持っている人々は自身の世界観を変えない（逆効果の可能性）ため","ファクトチェックを行う組織が常に政府と結託しているから","事実を確認する技術がまだ開発されておらず、主観に頼らざるを得ないため","ファクトチェックの結果を信じる人が誰一人として存在しないため"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '民主主義において「熟議」が重要視される理由は何か。', '["他者の意見を聴くプロセスを経て、自らの視点を相対化し、合意形成を目指すことが市民的徳性の涵養につながるから","多数決のみが常に絶対的な正義であり、少数意見を排除することが効率的だから","政治家が専門知識を有しており、市民は政治に関与すべきではないから","対立を極限まで先鋭化させることで、社会を刷新させるエネルギーが得られるから"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代の情報空間における「信頼」の危機について、最も正確な説明はどれか。', '["科学者やメディア等の既存の権威に対する信頼が低下し、何が真実かの判断基準が分散・崩壊していること","すべての情報が等しく信頼できると考えられ、情報の選別が行われないこと","SNSによるコミュニティ内での信頼関係が強固になりすぎ、社会全体の一体感が増していること","情報の信頼性を保証するための法整備が完結し、誰もが疑うことなく情報を受け入れていること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'AIが生成する「ディープフェイク」が民主主義の根幹を揺るがす最大の懸念は何か。', '["何が本物で何が偽物か判別できなくなることで、記録や証拠に基づく合意が困難になること","AIが政治家として立候補し、人間の能力を凌駕して当選すること","ディープフェイクが非常に高価で、一般人は決して利用できないこと","すべての人々がAIの生成物を完全に信頼し、疑わなくなること"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ポスト真実の時代において、小論文等で論じられるべき「健全な市民」のあるべき姿勢はどれか。', '["自らのバイアスを自覚し、異なる意見や不快な事実に対しても一定の知的謙虚さと批判的精神を持つこと","SNSのトレンドに従い、最も多くの支持を集めている意見を無批判に受け入れること","あらゆる情報源をシャットアウトし、自己の信念のみを内省的に追求し続けること","感情に訴えかける物語を構築し、他者を説得する技術を磨くこと"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ピエール・ブルデューが提唱した「文化資本」の概念において、家庭内で継承される言語能力や美的感性、教育的価値観などが個人の学業達成に与える影響を最も適切に説明しているものはどれか。', '["金銭的資産のみが学歴を決定し、非物質的な要素は学力と無関係である。","家庭の文化的な素養や言動様式が学校の評価基準と合致し、有利な結果をもたらす。","個人の努力さえあれば、文化資本の格差は完全に無効化できる。","文化資本は遺伝的な知能指数に直結しており、教育によって後天的に修正することは不可能である。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「親ガチャ」という語が現代日本で拡散する背景には、どのような社会認識の変化があるか。最も妥当なものを選べ。', '["努力が必ず報われるという能力主義（メリトクラシー）への信頼が揺らぎ、不平等が構造的であると捉えられるようになった。","公教育の質が向上した結果、家庭環境の差が学力に影響を与えなくなった。","個人の成功を親の資質にのみ帰属させ、個人の主体性を過大評価する傾向が強まった。","貧困層の社会的流動性が劇的に改善され、出自による格差が消失した。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '教育機会の平等について、機会の「形式的平等」と「実質的平等」の違いに関する記述として、最も適切なものはどれか。', '["形式的平等とは、すべての児童に異なる教育支援を提供し、結果の差を埋めることである。","実質的平等とは、出発条件の格差を考慮せず、同じ教育課程を課すことである。","形式的平等が、家庭環境や経済状況による差異を無視した法的な均等のみを指すのに対し、実質的平等はそれらの格差を埋める支援を含めた平等である。","現代の公教育においては、形式的平等よりも、能力主義を徹底する排除的な実質的平等が求められている。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「能力主義（メリトクラシー）」がもたらす逆説（マイケル・ヤングが指摘した弊害）として、最も的確なものはどれか。', '["教育の質が向上し、国家全体の生産性が無限に高まること。","社会的地位の差が個人の才能の差と見なされ、敗者が「自己責任」として冷遇されること。","家柄や身分による格差が完全に廃止され、真の平等が達成されること。","教育の機会が制限されることで、特定の階層のみが富を独占するようになること。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「教育の機会均等」を論じる際、公教育が担うべき役割として最も適切とされる考え方はどれか。', '["学校教育は、家庭環境に左右されず、個人の適性を最適化し、公平な競争環境を担保する機能を果たすべきである。","公教育は市場原理を導入し、競争に勝った生徒にのみ質の高い教育を集中配分すべきである。","家庭教育こそが最優先されるべきであり、学校教育は補助的な役割に留まるべきである。","公教育は一律の教育を行うべきではなく、親の所得に応じて教育内容を選択させるべきである。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'ジョン・ロールズの「公正としての正義」において、社会的に不遇な状況にある者の境遇を改善すべきだとする「格差原理」の趣旨として、正しいものはどれか。', '["才能ある者のみが最大限の利益を得る社会が、最も正義にかなう。","社会のすべての格差を完全になくし、全員が同一の資産を持つ状態を目指す。","社会の不平等の是正は、最も不遇な立場にある人々の期待値を最大化する場合にのみ許容される。","公教育においては、個人の努力以外の要因による不平等を考慮せず、競争を激化させるべきである。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「自己責任論」が教育格差の議論において批判される最大の理由は何か。', '["個人の努力を過小評価しすぎるから。","社会的な不平等が個人の努力不足という言葉で矮小化され、構造的な問題解決が阻害されるから。","個人の尊厳を尊重しすぎて、国家が教育に関与できなくなるから。","学力競争を過激化させ、日本の経済成長を阻害するから。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '文化的再生産論によれば、学校教育は階層格差を解消するのではなく、むしろ固定化させる機能を持つとされる。そのメカニズムとして最も妥当なものはどれか。', '["学校が特定の階級の文化を「正当な知」として特権化し、その文化を持たない層を無能と見なすから。","学費を無料にすることで、低所得層が教育に無関心になるから。","全ての子供に同じ教科書を与えることで、家庭による教育介入を防いでいるから。","学校教育の場では成績以外の能力は一切評価されないから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「社会的包摂（ソーシャル・インクルージョン）」の観点から教育政策を論じる際、最も重視される視点はどれか。', '["学力の高い生徒を隔離してエリート教育を徹底すること。","出身階層や経済的背景に関わらず、すべての子供が社会に参加できる基盤を教育によって構築すること。","親の職業選択の自由を守るために、公教育の介入を最小限に抑えること。","格差の原因を個人の資質の問題として処理し、自己啓発を促すこと。"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「教育の私事化（家庭の教育力の強調）」が進むことの懸念点として、最も妥当なものはどれか。', '["家庭の経済力や教養レベルの格差が直接的に子供の教育機会の格差となり、社会移動が困難になること。","公的な教育カリキュラムが廃止され、個人の自由が拡大すること。","学校教育の重要性が低下し、職業訓練の場として再定義されること。","地域社会との連携が強まり、教育の均質性が保たれること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', 'メリトクラシー（能力主義）に基づく社会における「勝者の傲慢」（マイケル・サンデル）とは、どのような態度を指すか。', '["自身の成功を単なる努力の成果と信じ、恵まれた環境という幸運を無視して、敗者を「努力不足」と断罪する態度。","社会貢献を目的として、自身の富を再分配しようとする公共的な態度。","運の要素を認め、他者への謙虚さと敬意を持って社会に参加する態度。","自身の能力が限定的であることを理解し、他者の助けを求める謙虚な態度。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '教育において「公平性」と「効率性」が対立する場合、社会政策としてどのような視点が求められるか。', '["効率性を最優先し、高能力者に投資することが常に長期的には公平性を生む。","公平性を追求すれば必ず経済発展が止まるため、教育は市場競争に委ねるべきである。","経済的な効率性のみならず、社会の分断を防ぎ、すべての者が能力を発揮できる公平な基盤形成を重視するべきである。","公平性は憲法上の義務であるため、効率性を一切考慮せず、全生徒に均等な予算を割り振るべきである。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代社会における教育の「選抜機能」が抱えるジレンマについて、最も適切な説明はどれか。', '["社会に必要な人材を選別する役割を担う一方で、その基準が既存の階層構造を再生産する役割も果たしていること。","能力主義を選抜の基準にすることで、誰からも納得される公平な社会が実現できること。","教育は選抜を廃止すべきであり、すべての生徒が同じ進路に進むのが最も正しいこと。","選抜機能は家庭環境を考慮しないため、親ガチャ問題を完全に解決できること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '学校教育において「学力」が多義的に捉えられる必要がある理由は何か。', '["特定の学力観（偏差値など）のみを重視すると、特定の家庭環境で育った能力しか評価されず、教育の機会均等が損なわれるから。","多様な学力観を持つことで、テストが不要になり、受験競争が消滅するから。","学力を定義しないことが、教育学上のもっとも先進的な理論であるから。","偏差値こそが唯一絶対の学力指標であり、多様性は学力を低下させる要因になるから。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「教育の機会の平等」を実現するための政策として、いわゆる「アファーマティブ・アクション（積極的差別是正措置）」の論理的根拠は何か。', '["特定のグループに対して優遇措置をとることは、過去の構造的不平等を埋め合わせ、実質的な機会の平等を達成するため。","個人の能力に関わらず、すべての市民に一定の給与を支給するため。","試験の結果よりも、性別や人種を優先することが社会の進歩に寄与するから。","形式的な平等を徹底するために、一切の配慮を排除し、完全な能力主義を導入するため。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '家庭環境が学業に及ぼす影響を最小化するために、学校現場で最も期待されているアプローチはどれか。', '["家庭の教育力の向上を促すための保護者向け教育の強化。","学校教育の補完的役割として、家庭教師や塾を公的に提供すること。","学校内での学習時間を増やし、環境による学習機会の格差を学校内で完結させること。","教育に格差があることを前提とし、家庭ごとに異なるカリキュラムを選択させること。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「親ガチャ論」に対する反論として、能力主義の擁護者が主張する論理として最も典型的なものはどれか。', '["親の格差は常に存在するが、本人の努力があれば、現代社会では誰でも成功できる。","親ガチャ論は、社会福祉の充実を求めるための唯一の正当な論理である。","親の影響力は遺伝的に決定されているため、そもそも論じる必要がない。","現代の教育システムは完全に中立であり、家庭環境の影響は統計的には存在しない。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '教育社会学において「文化的再生産」を食い止めるために必要とされる「ハビトゥス（個人の習性や振る舞い）」の転換とはどのようなことか。', '["学校が特定の文化を標準と見なさず、多様な価値観を肯定し、子供が自身の階層に関わらず可能性を広げられる環境を整えること。","全生徒に同じような趣味や振る舞いを強制することで、均質な社会を形成すること。","親が家庭教育を放棄し、教育の責任をすべて国家に移譲すること。","試験のみで個人の能力を測るシステムを強化し、家庭の影響を排除すること。"]', 0, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '現代日本の教育において、所得格差が学力格差に直結する傾向（経済格差と教育格差の相関）を緩和するために必要不可欠な政策的視点はどれか。', '["私立教育機関の優遇を強め、教育の質を高めること。","給食費の無償化のみですべての課題が解決すると信じること。","幼児教育から大学教育まで、家庭の経済状況によらず質の高い教育を受けられるような公共的な資金再分配を行うこと。","教育競争を激化させ、奨学金を全額返済義務のあるローンにすること。"]', 2, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('high_3', 'general_knowledge', '「教育の機会均等」は、単なるスタートラインを揃えること以上の意味を持つとされる。その根拠として最も妥当なものはどれか。', '["社会の格差を放置すれば社会の持続可能性が損なわれるため、家庭環境に関わらず誰もが自己実現できる環境こそが正義であるから。","教育の目的が国家の利益のために個人の能力を最大化させることにあるから。","平等とは全員が同じ職業に就くことであり、教育はそのための手段であるから。","能力のある者が富を得るのは自然の摂理であり、平等を追求する必要はないから。"]', 0, 3);
